              "\n",
              "<!DOCTYPE html>\n",
              "<html lang=\"en\">\n",
              "<head>\n",
              "<meta charset=\"UTF-8\">\n",
              "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n",
              "<link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n",
              "<link href=\"https://fonts.googleapis.com/icon?family=Material+Icons+Round\" rel=\"stylesheet\">\n",
              "<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.2/css/all.min.css\">\n",
              "<style>\n",
              "    :root {\n",
              "        --bg-amoled: #0B0C10;\n",
              "        --surface-card: #14151C;\n",
              "        --surface-inner: #1C1E26;\n",
              "        --border-distinct: #3C4252;\n",
              "        --primary-yellow: #FFD600;\n",
              "        --dark-yellow: #E6C200;\n",
              "        --highlight-cta: #EF4444;\n",
              "        --text-primary: #FFFFFF;\n",
              "        --text-secondary: #F2F3F7;\n",
              "        --text-muted: #C2C6D2;\n",
              "        --card-glow: rgba(255, 214, 0, 0.14);\n",
              "        --card-shadow: 0 14px 40px rgba(0, 0, 0, 0.6);\n",
              "        --modal-bg: #14151C;\n",
              "        --chip-text: #FFFFFF;\n",
              "        --input-bg: #1C1E26;\n",
              "        --btn-text-on-accent: #000000;\n",
              "        --font: 'Plus Jakarta Sans', sans-serif;\n",
              "    }\n",
              "\n",
              "    [data-theme=\"dark\"] {\n",
              "        --bg-amoled: #0B0C10;\n",
              "        --surface-card: #14151C;\n",
              "        --surface-inner: #1C1E26;\n",
              "        --border-distinct: #3C4252;\n",
              "        --primary-yellow: #FFD600;\n",
              "        --dark-yellow: #E6C200;\n",
              "        --highlight-cta: #EF4444;\n",
              "        --text-primary: #FFFFFF;\n",
              "        --text-secondary: #F2F3F7;\n",
              "        --text-muted: #C2C6D2;\n",
              "        --card-glow: rgba(255, 214, 0, 0.14);\n",
              "        --card-shadow: 0 14px 40px rgba(0, 0, 0, 0.6);\n",
              "        --modal-bg: #14151C;\n",
              "        --chip-text: #FFFFFF;\n",
              "        --input-bg: #1C1E26;\n",
              "        --btn-text-on-accent: #000000;\n",
              "    }\n",
              "\n",
              "    [data-theme=\"light\"] {\n",
              "        --bg-amoled: #F5F7FA;\n",
              "        --surface-card: #FFFFFF;\n",
              "        --surface-inner: #F0F2F6;\n",
              "        --border-distinct: #DCE1E8;\n",
              "        --primary-yellow: #EAB308;\n",
              "        --dark-yellow: #CA8A04;\n",
              "        --highlight-cta: #DC2626;\n",
              "        --text-primary: #0F172A;\n",
              "        --text-secondary: #334155;\n",
              "        --text-muted: #64748B;\n",
              "        --card-glow: rgba(234, 179, 8, 0.12);\n",
              "        --card-shadow: 0 6px 20px rgba(0, 0, 0, 0.06), 0 1px 3px rgba(0, 0, 0, 0.03);\n",
              "        --modal-bg: #FFFFFF;\n",
              "        --chip-text: #0F172A;\n",
              "        --input-bg: #F8FAFC;\n",
              "        --btn-text-on-accent: #000000;\n",
              "    }\n",
              "\n",
              "    :root {\n",
              "        --app-viewport-h: 580px;\n",
              "        --nav-height: 54px;\n",
              "    }\n",
              "    @media (min-width: 768px) {\n",
              "        :root {\n",
              "            --app-viewport-h: 720px;\n",
              "            --nav-height: 60px;\n",
              "        }\n",
              "    }\n",
              "\n",
              "    html, body {\n",
              "        background-color: var(--bg-amoled);\n",
              "        color: var(--text-primary);\n",
              "        font-family: var(--font);\n",
              "        margin: 0;\n",
              "        padding: 0;\n",
              "        width: 100%;\n",
              "        height: var(--app-viewport-h);\n",
              "        max-height: var(--app-viewport-h);\n",
              "        min-height: var(--app-viewport-h);\n",
              "        overflow: hidden !important;\n",
              "        position: relative !important;\n",
              "        box-sizing: border-box;\n",
              "        -webkit-font-smoothing: antialiased;\n",
              "        transition: background-color 0.25s ease, color 0.25s ease;\n",
              "    }\n",
              "\n",
              "    .md3-spinner { animation: md3-rotate 2s linear infinite; transform-origin: center center; width: 56px; height: 56px; margin-bottom: 24px; }\n",
              "    .md3-spinner circle { stroke: var(--primary-yellow); stroke-width: 4; stroke-dasharray: 1, 200; stroke-dashoffset: 0; animation: md3-dash 1.5s ease-in-out infinite; stroke-linecap: round; fill: none; }\n",
              "    @keyframes md3-rotate { 100% { transform: rotate(360deg); } }\n",
              "    @keyframes md3-dash {\n",
              "        0% { stroke-dasharray: 1, 200; stroke-dashoffset: 0; }\n",
              "        50% { stroke-dasharray: 89, 200; stroke-dashoffset: -35px; }\n",
              "        100% { stroke-dasharray: 89, 200; stroke-dashoffset: -124px; }\n",
              "    }\n",
              "\n",
              "    .fa-spin { animation: fa-spin 1s infinite linear; }\n",
              "    @keyframes fa-spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(359deg); } }\n",
              "\n",
              "    .wavy-progress-bg { width: 220px; height: 6px; background: var(--surface-inner); border-radius: 10px; overflow: hidden; position: relative; margin-bottom: 8px; border: 1px solid var(--border-distinct); }\n",
              "    .wavy-progress-fill { height: 100%; width: 0%; background: repeating-linear-gradient(45deg, var(--primary-yellow) 0%, var(--dark-yellow) 25%, var(--primary-yellow) 50%); background-size: 200% 100%; animation: wave-move 2s linear infinite; transition: width 0.3s ease; border-radius: 10px; }\n",
              "    @keyframes wave-move { 0% { background-position: 100% 0; } 100% { background-position: -100% 0; } }\n",
              "\n",
              "    /* Setup Screen: Mobile par Compact (260px) aur Desktop par Large & Proportional (380px) */\n",
              "    #startupLoader {\n",
              "        position: fixed !important;\n",
              "        top: 50% !important;\n",
              "        left: 50% !important;\n",
              "        transform: translate(-50%, -50%) !important;\n",
              "        width: 84% !important;\n",
              "        max-width: 260px !important;\n",
              "        height: auto !important;\n",
              "        min-height: auto !important;\n",
              "        background: var(--surface-card) !important;\n",
              "        border: 1px solid var(--border-distinct) !important;\n",
              "        border-radius: 20px !important;\n",
              "        display: flex;\n",
              "        flex-direction: column !important;\n",
              "        align-items: center !important;\n",
              "        justify-content: center !important;\n",
              "        transition: opacity 0.25s ease;\n",
              "        margin: 0 !important;\n",
              "        padding: 16px 14px !important;\n",
              "        box-sizing: border-box !important;\n",
              "        box-shadow: var(--card-shadow) !important;\n",
              "        z-index: 9999 !important;\n",
              "    }\n",
              "    #startupLoader.loader-hidden,\n",
              "    #startupLoader[style*=\"display: none\"] {\n",
              "        display: none !important;\n",
              "        opacity: 0 !important;\n",
              "        visibility: hidden !important;\n",
              "        pointer-events: none !important;\n",
              "    }\n",
              "    #startupLoader .md3-spinner {\n",
              "        width: 32px !important;\n",
              "        height: 32px !important;\n",
              "        margin-bottom: 8px !important;\n",
              "    }\n",
              "    .loader-title {\n",
              "        font-size: 13px !important;\n",
              "        font-weight: 800 !important;\n",
              "        margin-bottom: 3px !important;\n",
              "        text-align: center;\n",
              "        color: var(--text-primary);\n",
              "        letter-spacing: -0.2px;\n",
              "    }\n",
              "    .loader-subtitle {\n",
              "        font-size: 9.5px !important;\n",
              "        color: var(--text-muted);\n",
              "        margin-bottom: 8px !important;\n",
              "        text-align: center;\n",
              "        line-height: 1.35;\n",
              "    }\n",
              "    #startupLoader #loaderHintText {\n",
              "        font-size: 9.5px !important;\n",
              "        margin-bottom: 8px !important;\n",
              "        line-height: 1.35;\n",
              "    }\n",
              "    #startupLoader #awakePromptBadge {\n",
              "        padding: 4px 10px !important;\n",
              "        font-size: 9px !important;\n",
              "        border-radius: 100px !important;\n",
              "    }\n",
              "    #startupLoader #loaderPercentage {\n",
              "        font-size: 24px !important;\n",
              "        margin-bottom: 4px !important;\n",
              "        letter-spacing: -0.5px !important;\n",
              "    }\n",
              "    #startupLoader .wavy-progress-bg {\n",
              "        width: 160px !important;\n",
              "        height: 4.5px !important;\n",
              "        margin-bottom: 4px !important;\n",
              "        border-radius: 100px !important;\n",
              "    }\n",
              "    .loader-timer {\n",
              "        font-size: 10.5px !important;\n",
              "        font-weight: 700;\n",
              "        color: var(--primary-yellow);\n",
              "        font-variant-numeric: tabular-nums;\n",
              "        margin-top: 2px !important;\n",
              "        margin-bottom: 0 !important;\n",
              "    }\n",
              "\n",
              "    /* Desktop View Scaling for Setup Screen */\n",
              "    @media (min-width: 768px) {\n",
              "        #startupLoader {\n",
              "            max-width: 380px !important;\n",
              "            padding: 24px 22px !important;\n",
              "            border-radius: 24px !important;\n",
              "        }\n",
              "        #startupLoader .md3-spinner {\n",
              "            width: 44px !important;\n",
              "            height: 44px !important;\n",
              "            margin-bottom: 12px !important;\n",
              "        }\n",
              "        .loader-title {\n",
              "            font-size: 16px !important;\n",
              "            margin-bottom: 5px !important;\n",
              "        }\n",
              "        .loader-subtitle {\n",
              "            font-size: 11px !important;\n",
              "            margin-bottom: 12px !important;\n",
              "        }\n",
              "        #startupLoader #loaderHintText {\n",
              "            font-size: 11px !important;\n",
              "            margin-bottom: 12px !important;\n",
              "        }\n",
              "        #startupLoader #loaderPercentage {\n",
              "            font-size: 32px !important;\n",
              "            margin-bottom: 6px !important;\n",
              "        }\n",
              "        #startupLoader .wavy-progress-bg {\n",
              "            width: 210px !important;\n",
              "            height: 6px !important;\n",
              "            margin-bottom: 6px !important;\n",
              "        }\n",
              "        .loader-timer {\n",
              "            font-size: 12px !important;\n",
              "            margin-top: 4px !important;\n",
              "        }\n",
              "    }\n",
              "\n",
              "    /* Universal Kill for All Horizontal Scrollbars */\n",
              "    *::-webkit-scrollbar:horizontal {\n",
              "        display: none !important;\n",
              "        height: 0px !important;\n",
              "        width: 0px !important;\n",
              "        background: transparent !important;\n",
              "        opacity: 0 !important;\n",
              "        pointer-events: none !important;\n",
              "    }\n",
              "    .chip-container, .chip-container * {\n",
              "        scrollbar-width: none !important;\n",
              "        -ms-overflow-style: none !important;\n",
              "    }\n",
              "    .chip-container::-webkit-scrollbar {\n",
              "        display: none !important;\n",
              "        height: 0px !important;\n",
              "        width: 0px !important;\n",
              "    }\n",
              "\n",
              "    /* Clean Scrollable Viewport with Vertical-Only 5px Slim Scrollbar */\n",
              "    .studio-canvas {\n",
              "        width: 100%;\n",
              "        max-width: 1200px;\n",
              "        height: calc(var(--app-viewport-h) - var(--nav-height)) !important;\n",
              "        max-height: calc(var(--app-viewport-h) - var(--nav-height)) !important;\n",
              "        margin: 0 auto;\n",
              "        padding: 12px 14px !important;\n",
              "        padding-bottom: calc(var(--nav-height) + 20px) !important;\n",
              "        box-sizing: border-box;\n",
              "        display: none;\n",
              "        flex-direction: column;\n",
              "        gap: 12px;\n",
              "        overflow-y: auto !important;\n",
              "        overflow-x: hidden !important;\n",
              "        -webkit-overflow-scrolling: touch;\n",
              "        scrollbar-width: thin;\n",
              "        scrollbar-color: rgba(255, 214, 0, 0.28) transparent;\n",
              "    }\n",
              "    .studio-canvas::-webkit-scrollbar {\n",
              "        width: 5px;\n",
              "        height: 0px !important;\n",
              "    }\n",
              "    .studio-canvas::-webkit-scrollbar:vertical {\n",
              "        width: 5px;\n",
              "    }\n",
              "    .studio-canvas::-webkit-scrollbar-track {\n",
              "        background: transparent;\n",
              "    }\n",
              "    .studio-canvas::-webkit-scrollbar-thumb {\n",
              "        background: rgba(255, 214, 0, 0.28);\n",
              "        border-radius: 10px;\n",
              "    }\n",
              "    .studio-canvas::-webkit-scrollbar-thumb:hover {\n",
              "        background: rgba(255, 214, 0, 0.45);\n",
              "    }\n",
              "\n",
              "    /* Clean Fixed Bottom Navbar (Locked at bottom, never jumps on upload) */\n",
              "    .bottom-navbar {\n",
              "        position: fixed !important;\n",
              "        bottom: 0 !important;\n",
              "        left: 0 !important;\n",
              "        right: 0 !important;\n",
              "        transform: translateZ(0) !important;\n",
              "        -webkit-transform: translateZ(0) !important;\n",
              "        width: 100% !important;\n",
              "        height: var(--nav-height) !important;\n",
              "        background-color: var(--surface-card) !important;\n",
              "        border-top: 1px solid var(--border-distinct) !important;\n",
              "        display: flex !important;\n",
              "        justify-content: space-around !important;\n",
              "        align-items: center !important;\n",
              "        z-index: 1000 !important;\n",
              "        box-sizing: border-box !important;\n",
              "        padding: 0 16px !important;\n",
              "        box-shadow: 0 -4px 18px rgba(0, 0, 0, 0.4) !important;\n",
              "    }\n",
              "    .dashboard-layout {\n",
              "        display: grid;\n",
              "        grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));\n",
              "        gap: 12px;\n",
              "        width: 100%;\n",
              "        box-sizing: border-box;\n",
              "    }\n",
              "    /* Full-width stretch for Tuning, 4X, and Queue cards on desktop */\n",
              "    .span-full {\n",
              "        grid-column: 1 / -1 !important;\n",
              "    }\n",
              "\n",
              "    .view-section { display: none; flex-direction: column; gap: 10px; width: 100%; box-sizing: border-box; }\n",
              "    .view-section.active-view {\n",
              "        display: flex;\n",
              "        animation: pageEntranceAnim 0.25s cubic-bezier(0.16, 1, 0.3, 1) forwards;\n",
              "        will-change: opacity, transform;\n",
              "    }\n",
              "    @keyframes pageEntranceAnim {\n",
              "        0% { opacity: 0; transform: translateY(10px) scale(0.985); }\n",
              "        100% { opacity: 1; transform: translateY(0) scale(1); }\n",
              "    }\n",
              "    @keyframes slideFadeIn { to { opacity: 1; transform: translateY(0); } }\n",
              "\n",
              "    @keyframes toastInAnim {\n",
              "        from { opacity: 0; transform: translateY(10px) scale(0.92); }\n",
              "        to { opacity: 1; transform: translateY(0) scale(1); }\n",
              "    }\n",
              "    @keyframes toastOutAnim {\n",
              "        from { opacity: 1; transform: translateY(0) scale(1); }\n",
              "        to { opacity: 0; transform: translateY(-8px) scale(0.92); }\n",
              "    }\n",
              "\n",
              "    /* Crown Twixtor Smooth Card Physics & Cascade System */\n",
              "    .card-enter-anim {\n",
              "        animation: cardExpandIn 0.28s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;\n",
              "        overflow: hidden;\n",
              "        will-change: max-height, opacity, transform;\n",
              "    }\n",
              "    .card-pop-in {\n",
              "        animation: cardCascadeIn 0.28s cubic-bezier(0.2, 0.8, 0.2, 1) backwards;\n",
              "        will-change: opacity, transform;\n",
              "    }\n",
              "    @keyframes cardCascadeIn {\n",
              "        0% { opacity: 0; transform: translateY(10px) scale(0.97); }\n",
              "        100% { opacity: 1; transform: translateY(0) scale(1); }\n",
              "    }\n",
              "    .card-deleting-state {\n",
              "        opacity: 0.45 !important;\n",
              "        pointer-events: none !important;\n",
              "    }\n",
              "    .card-collapse-out {\n",
              "        opacity: 0 !important;\n",
              "        transform: translateX(18px) scale(0.96) !important;\n",
              "        height: 0px !important;\n",
              "        padding-top: 0px !important;\n",
              "        padding-bottom: 0px !important;\n",
              "        margin-top: -8px !important;\n",
              "        margin-bottom: 0px !important;\n",
              "        border-width: 0px !important;\n",
              "        overflow: hidden !important;\n",
              "        pointer-events: none !important;\n",
              "        transition: opacity 0.2s ease, transform 0.22s cubic-bezier(0.2, 0.8, 0.2, 1), height 0.22s cubic-bezier(0.4, 0, 0.2, 1), margin 0.22s ease, padding 0.22s ease !important;\n",
              "    }\n",
              "    @keyframes cardExpandIn {\n",
              "        0% { max-height: 0px; opacity: 0; transform: translateY(-8px) scale(0.97); padding-top: 0; padding-bottom: 0; margin-bottom: -8px; }\n",
              "        100% { max-height: 80px; opacity: 1; transform: translateY(0) scale(1); }\n",
              "    }\n",
              "\n",
              "    .app-header { display: flex; justify-content: space-between; align-items: center; padding: 6px 4px; border-bottom: 1px solid var(--border-distinct); margin-bottom: 2px; position: relative; }\n",
              "    .brand-link-wrapper { display: flex; align-items: center; gap: 8px; text-decoration: none; cursor: pointer; transition: transform 0.2s; }\n",
              "    .brand-link-wrapper:active { transform: scale(0.9) translateY(2px); }\n",
              "    .app-title-main { font-size: 16px; font-weight: 800; letter-spacing: -0.4px; color: var(--text-primary); margin: 0; }\n",
              "    .app-title-main span { color: var(--primary-yellow); }\n",
              "    .app-title-sub { font-size: 14px; font-weight: 800; color: var(--text-primary); margin: 0; margin-left: 2px; }\n",
              "\n",
              "    .social-symbol {\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        width: 22px;\n",
              "        height: 22px;\n",
              "        border-radius: 50%;\n",
              "        color: var(--text-muted);\n",
              "        text-decoration: none;\n",
              "        transition: 0.2s;\n",
              "        flex-shrink: 0;\n",
              "        border: none !important;\n",
              "        background: transparent !important;\n",
              "        box-shadow: none !important;\n",
              "    }\n",
              "    .social-symbol:hover { color: var(--text-primary); }\n",
              "    .social-symbol.yt i { color: #FF0000; font-size: 11px; }\n",
              "    .social-symbol.dc i { color: #5865F2; font-size: 11px; }\n",
              "    .social-symbol.wb i { color: var(--primary-yellow); font-size: 11px; }\n",
              "\n",
              "    .icon-btn { color: var(--primary-yellow); cursor: pointer; font-size: 18px; transition: 0.2s; }\n",
              "\n",
              "    .notify-dropdown { position: absolute; right: 0; top: 42px; background: var(--surface-card); border: 1px solid var(--border-distinct); border-radius: 14px; padding: 12px; width: 220px; box-shadow: var(--card-shadow); z-index: 100; display: none; flex-direction: column; gap: 8px; }\n",
              "    .notify-dropdown.show { display: flex; animation: slideFadeIn 0.2s forwards; }\n",
              "\n",
              "    .compose-card {\n",
              "        position: relative;\n",
              "        background: var(--surface-card);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        box-shadow: var(--card-shadow);\n",
              "        border-radius: 18px;\n",
              "        padding: 10px 12px;\n",
              "        display: flex;\n",
              "        flex-direction: column;\n",
              "        gap: 8px;\n",
              "        box-sizing: border-box;\n",
              "        width: 100%;\n",
              "        transition: background 0.25s ease, border-color 0.25s ease;\n",
              "    }\n",
              "    .component-label-group { display: flex; align-items: center; gap: 6px; }\n",
              "    .component-label-group .icon { font-size: 16px; color: var(--primary-yellow); }\n",
              "    .component-title { font-size: 12px; font-weight: 700; margin: 0; color: var(--text-primary); }\n",
              "\n",
              "    .upload-box { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 22px 8px; text-align: center; border: 2px dashed var(--border-distinct); border-radius: 20px; transition: 0.2s; cursor: pointer; background: var(--surface-inner); }\n",
              "    .upload-box:hover { border-color: var(--primary-yellow); background: var(--card-glow); }\n",
              "    .upload-box.drag-over { border-color: var(--primary-yellow); background: var(--card-glow); }\n",
              "    .upload-circle { width: 48px; height: 48px; border-radius: 50%; background-color: var(--surface-card); display: flex; align-items: center; justify-content: center; margin-bottom: 10px; border: 1px solid var(--border-distinct); }\n",
              "    .upload-circle .icon { color: var(--primary-yellow); font-size: 22px; }\n",
              "    .upload-title { font-size: 15px; font-weight: 700; color: var(--text-primary); margin-bottom: 4px; }\n",
              "    .upload-subtitle { font-size: 12px; color: var(--text-muted); }\n",
              "\n",
              "    .file-stack { display: flex; flex-direction: column; gap: 6px; margin-top: 4px; width: 100%; }\n",
              "\n",
              "    .preview-panel {\n",
              "        background: var(--surface-inner);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 14px !important;\n",
              "        padding: 5px 8px;\n",
              "        display: flex !important;\n",
              "        align-items: center !important;\n",
              "        gap: 7px !important;\n",
              "        width: 100%;\n",
              "        box-sizing: border-box;\n",
              "        min-width: 0;\n",
              "        position: relative;\n",
              "        transition: opacity 0.2s ease, transform 0.22s cubic-bezier(0.2, 0.8, 0.2, 1), height 0.22s cubic-bezier(0.4, 0, 0.2, 1), margin 0.22s ease, padding 0.22s ease !important;\n",
              "    }\n",
              "    .preview-panel:hover {\n",
              "        border-color: var(--primary-yellow);\n",
              "    }\n",
              "    .preview-panel.unsupported {\n",
              "        opacity: 0.75;\n",
              "        border-color: var(--highlight-cta);\n",
              "    }\n",
              "\n",
              "    .file-checkbox-wrapper { display: flex !important; align-items: center !important; justify-content: center !important; flex-shrink: 0 !important; }\n",
              "    .file-checkbox {\n",
              "        -webkit-appearance: none;\n",
              "        appearance: none;\n",
              "        width: 14px !important;\n",
              "        height: 14px !important;\n",
              "        border-radius: 50% !important;\n",
              "        border: 1.5px solid var(--border-distinct) !important;\n",
              "        background: var(--surface-card) !important;\n",
              "        cursor: pointer !important;\n",
              "        position: relative !important;\n",
              "        transition: all 0.2s ease !important;\n",
              "        margin: 0 !important;\n",
              "        display: inline-block !important;\n",
              "        flex-shrink: 0 !important;\n",
              "    }\n",
              "    .file-checkbox:checked {\n",
              "        background-color: var(--primary-yellow) !important;\n",
              "        border-color: var(--primary-yellow) !important;\n",
              "    }\n",
              "    .file-checkbox:checked::after {\n",
              "        content: '' !important;\n",
              "        position: absolute !important;\n",
              "        left: 4px !important;\n",
              "        top: 1.2px !important;\n",
              "        width: 3px !important;\n",
              "        height: 6.5px !important;\n",
              "        border: solid #000000 !important;\n",
              "        border-width: 0 1.5px 1.5px 0 !important;\n",
              "        transform: rotate(45deg) !important;\n",
              "    }\n",
              "\n",
              "    .preview-media-container {\n",
              "        width: 34px !important;\n",
              "        height: 24px !important;\n",
              "        border-radius: 6px !important;\n",
              "        background: var(--surface-card);\n",
              "        overflow: hidden;\n",
              "        flex-shrink: 0 !important;\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        cursor: pointer;\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        position: relative;\n",
              "    }\n",
              "    .preview-media-container img, .preview-media-container video {\n",
              "        width: 100% !important;\n",
              "        height: 100% !important;\n",
              "        object-fit: cover !important;\n",
              "        pointer-events: none;\n",
              "    }\n",
              "\n",
              "    .preview-details {\n",
              "        display: flex !important;\n",
              "        flex-direction: column !important;\n",
              "        gap: 1px !important;\n",
              "        overflow: hidden;\n",
              "        flex: 1 1 0% !important;\n",
              "        min-width: 0 !important;\n",
              "    }\n",
              "    .preview-filename {\n",
              "        font-size: 11px !important;\n",
              "        font-weight: 700 !important;\n",
              "        color: var(--text-primary);\n",
              "        white-space: nowrap !important;\n",
              "        overflow: hidden !important;\n",
              "        text-overflow: ellipsis !important;\n",
              "        cursor: pointer;\n",
              "        line-height: 1.2 !important;\n",
              "    }\n",
              "    .meta-sub-metrics {\n",
              "        font-size: 8px !important;\n",
              "        color: var(--text-muted);\n",
              "        font-weight: 600;\n",
              "        display: flex !important;\n",
              "        align-items: center !important;\n",
              "        flex-wrap: wrap !important;\n",
              "        gap: 3px !important;\n",
              "        row-gap: 3px !important;\n",
              "        white-space: normal !important;\n",
              "        line-height: 1 !important;\n",
              "        margin-top: 1px !important;\n",
              "        min-width: 0 !important;\n",
              "        max-width: 100% !important;\n",
              "    }\n",
              "    .tech-pill {\n",
              "        background: rgba(255, 214, 0, 0.15) !important;\n",
              "        color: var(--primary-yellow) !important;\n",
              "        font-size: 7.5px !important;\n",
              "        font-weight: 800 !important;\n",
              "        padding: 1.5px 6.5px !important;\n",
              "        border-radius: 100px !important;\n",
              "        border: 1px solid rgba(255, 214, 0, 0.35) !important;\n",
              "        white-space: nowrap !important;\n",
              "        line-height: 1 !important;\n",
              "    }\n",
              "    .cancel-upload-btn {\n",
              "        position: absolute;\n",
              "        right: 8px;\n",
              "        color: var(--text-muted);\n",
              "        cursor: pointer;\n",
              "        font-size: 15px;\n",
              "        transition: 0.2s;\n",
              "    }\n",
              "    .cancel-upload-btn:hover { color: var(--highlight-cta); }\n",
              "\n",
              "    .action-button-main {\n",
              "        width: 100%;\n",
              "        background: linear-gradient(135deg, var(--primary-yellow), var(--dark-yellow));\n",
              "        color: var(--btn-text-on-accent);\n",
              "        border: none;\n",
              "        padding: 9px 16px;\n",
              "        border-radius: 100px;\n",
              "        font-family: var(--font);\n",
              "        font-size: 12px;\n",
              "        font-weight: 800;\n",
              "        cursor: pointer;\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        text-align: center;\n",
              "        gap: 6px;\n",
              "        box-shadow: 0 4px 16px var(--card-glow);\n",
              "        box-sizing: border-box;\n",
              "        margin: 2px 0;\n",
              "        transition: 0.2s;\n",
              "        text-transform: uppercase;\n",
              "        letter-spacing: 0.4px;\n",
              "        line-height: 1;\n",
              "    }\n",
              "    .action-button-main .icon {\n",
              "        font-size: 15px !important;\n",
              "        display: inline-flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        line-height: 1;\n",
              "        margin: 0 !important;\n",
              "        vertical-align: middle;\n",
              "    }\n",
              "\n",
              "    /* Responsive wrap to prevent button squishing on mobile */\n",
              "    .flex-row-grid { display: flex; gap: 8px; width: 100%; box-sizing: border-box; flex-wrap: wrap; }\n",
              "    .flex-row-grid > * { flex: 1 1 calc(33.33% - 8px); min-width: 80px; }\n",
              "    .flex-col-grid { flex: 1; display: flex; flex-direction: column; gap: 10px; min-width: 0; }\n",
              "    .chip-container {\n",
              "        display: flex !important;\n",
              "        gap: 6px !important;\n",
              "        flex-wrap: nowrap !important;\n",
              "        overflow-x: auto !important;\n",
              "        overflow-y: hidden !important;\n",
              "        width: 100% !important;\n",
              "        max-width: 100% !important;\n",
              "        box-sizing: border-box !important;\n",
              "        padding: 2px 18px 2px 1px !important;\n",
              "        -webkit-overflow-scrolling: touch !important;\n",
              "        -webkit-mask-image: linear-gradient(to right, black calc(100% - 24px), transparent 100%);\n",
              "        mask-image: linear-gradient(to right, black calc(100% - 24px), transparent 100%);\n",
              "        scrollbar-width: none !important;\n",
              "        -ms-overflow-style: none !important;\n",
              "    }\n",
              "    .chip-container::-webkit-scrollbar {\n",
              "        display: none !important;\n",
              "        width: 0px !important;\n",
              "        height: 0px !important;\n",
              "    }\n",
              "    .selectable-chip {\n",
              "        padding: 6px 12px !important;\n",
              "        border-radius: 100px !important;\n",
              "        font-size: 11px !important;\n",
              "        font-weight: 700 !important;\n",
              "        border: 1px solid var(--border-distinct) !important;\n",
              "        background-color: var(--surface-inner) !important;\n",
              "        color: var(--chip-text) !important;\n",
              "        cursor: pointer !important;\n",
              "        flex-shrink: 0 !important;\n",
              "        white-space: nowrap !important;\n",
              "        transition: all 0.2s ease !important;\n",
              "    }\n",
              "    .selectable-chip.active {\n",
              "        background-color: var(--primary-yellow) !important;\n",
              "        color: var(--btn-text-on-accent) !important;\n",
              "        border-color: var(--primary-yellow) !important;\n",
              "        font-weight: 800 !important;\n",
              "    }\n",
              "    .block-selector {\n",
              "        width: 100% !important;\n",
              "        padding: 5px 3px !important;\n",
              "        border-radius: 100px !important;\n",
              "        font-family: var(--font) !important;\n",
              "        font-size: 10.5px !important;\n",
              "        font-weight: 700 !important;\n",
              "        background-color: var(--surface-inner) !important;\n",
              "        color: var(--chip-text) !important;\n",
              "        border: 1px solid var(--border-distinct) !important;\n",
              "        cursor: pointer !important;\n",
              "        text-align: center !important;\n",
              "        box-sizing: border-box !important;\n",
              "        white-space: nowrap !important;\n",
              "        transition: all 0.2s ease !important;\n",
              "    }\n",
              "    .block-selector.active {\n",
              "        background-color: var(--primary-yellow) !important;\n",
              "        color: var(--btn-text-on-accent) !important;\n",
              "        border-color: var(--primary-yellow) !important;\n",
              "        font-weight: 800 !important;\n",
              "    }\n",
              "\n",
              "    .slider-info-row { display: flex; justify-content: space-between; align-items: center; width: 100%; }\n",
              "    .badge-pills { font-size: 14px; font-weight: 800; color: var(--primary-yellow); }\n",
              "    .range-container { position: relative; width: 100%; padding: 4px 0; }\n",
              "    .range-input {\n",
              "        -webkit-appearance: none;\n",
              "        appearance: none;\n",
              "        width: 100%;\n",
              "        height: 24px !important;\n",
              "        background: transparent !important;\n",
              "        border: none !important;\n",
              "        outline: none;\n",
              "        cursor: pointer;\n",
              "        margin: 0;\n",
              "        padding: 0;\n",
              "        transform: none !important;\n",
              "        transition: none !important;\n",
              "    }\n",
              "    .range-input:active, .range-input.node-pressed {\n",
              "        transform: none !important;\n",
              "        opacity: 1 !important;\n",
              "    }\n",
              "    .range-input::-webkit-slider-runnable-track {\n",
              "        width: 100%;\n",
              "        height: 6px !important;\n",
              "        background: var(--surface-inner);\n",
              "        border-radius: 100px;\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        cursor: pointer;\n",
              "    }\n",
              "    .range-input::-webkit-slider-thumb {\n",
              "        -webkit-appearance: none;\n",
              "        appearance: none;\n",
              "        width: 20px !important;\n",
              "        height: 20px !important;\n",
              "        border-radius: 50%;\n",
              "        background: var(--primary-yellow);\n",
              "        cursor: pointer;\n",
              "        box-shadow: 0 2px 6px rgba(0,0,0,0.3);\n",
              "        margin-top: -7px !important;\n",
              "        transform: none !important;\n",
              "        border: none;\n",
              "    }\n",
              "    .range-input::-moz-range-track {\n",
              "        width: 100%;\n",
              "        height: 6px !important;\n",
              "        background: var(--surface-inner);\n",
              "        border-radius: 100px;\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        cursor: pointer;\n",
              "    }\n",
              "    .range-input::-moz-range-thumb {\n",
              "        width: 20px !important;\n",
              "        height: 20px !important;\n",
              "        border-radius: 50%;\n",
              "        background: var(--primary-yellow);\n",
              "        cursor: pointer;\n",
              "        border: none;\n",
              "        box-shadow: 0 2px 6px rgba(0,0,0,0.3);\n",
              "    }\n",
              "    .slider-labels { display: flex; justify-content: space-between; font-size: 12px; font-weight: 600; color: var(--text-muted); }\n",
              "\n",
              "    /* Switch Row with Anti-Overflow Containment */\n",
              "    .switch-row {\n",
              "        display: flex;\n",
              "        justify-content: space-between;\n",
              "        align-items: center;\n",
              "        padding: 3px 0;\n",
              "        gap: 8px;\n",
              "        width: 100%;\n",
              "        box-sizing: border-box;\n",
              "    }\n",
              "    .switch-row .component-label-group {\n",
              "        flex: 1;\n",
              "        min-width: 0;\n",
              "        overflow: hidden;\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        gap: 8px;\n",
              "    }\n",
              "    .switch-row .component-label-group > div {\n",
              "        min-width: 0;\n",
              "        flex: 1;\n",
              "        overflow: hidden;\n",
              "    }\n",
              "    .switch-row span, .switch-row .component-title {\n",
              "        white-space: nowrap;\n",
              "        overflow: hidden;\n",
              "        text-overflow: ellipsis;\n",
              "        display: block;\n",
              "        max-width: 100%;\n",
              "    }\n",
              "    .switch-widget {\n",
              "        position: relative;\n",
              "        display: inline-block;\n",
              "        width: 40px;\n",
              "        height: 22px;\n",
              "        flex-shrink: 0 !important;\n",
              "        margin-left: auto;\n",
              "    }\n",
              "    .switch-widget input { opacity: 0; width: 0; height: 0; }\n",
              "    .switch-slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: var(--surface-inner); transition: 0.2s; border-radius: 34px; border: 1px solid var(--border-distinct); }\n",
              "    .switch-slider:before { position: absolute; content: \"\"; height: 14px; width: 14px; left: 3px; bottom: 3px; background-color: var(--text-muted); transition: 0.2s; border-radius: 50%; }\n",
              "    input:checked + .switch-slider { background-color: var(--primary-yellow); border-color: var(--primary-yellow); }\n",
              "    input:checked + .switch-slider:before { transform: translateX(18px); background-color: #000000; }\n",
              "\n",
              "    .custom-select { background-color: var(--surface-inner); border: 1px solid var(--border-distinct); color: var(--text-primary); border-radius: 12px; padding: 5px 10px; font-family: var(--font); font-size: 12px; font-weight: 600; outline: none; cursor: pointer; }\n",
              "    .custom-select:focus { border-color: var(--primary-yellow); }\n",
              "\n",
              "    .custom-model-drawer {\n",
              "        display: none;\n",
              "        flex-direction: column;\n",
              "        gap: 8px;\n",
              "        background: var(--surface-inner);\n",
              "        border: 1px dashed var(--border-distinct);\n",
              "        border-radius: 14px;\n",
              "        padding: 10px;\n",
              "        margin-top: 4px;\n",
              "        animation: slideFadeIn 0.25s ease forwards;\n",
              "        box-sizing: border-box;\n",
              "        width: 100%;\n",
              "    }\n",
              "    .custom-model-drawer.expanded { display: flex; }\n",
              "    .model-upload-btn {\n",
              "        background: var(--surface-card);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 100px;\n",
              "        padding: 8px 14px;\n",
              "        color: var(--text-primary);\n",
              "        font-family: var(--font);\n",
              "        font-size: 12px;\n",
              "        font-weight: 700;\n",
              "        cursor: pointer;\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        gap: 6px;\n",
              "        transition: all 0.2s ease;\n",
              "    }\n",
              "    .model-upload-btn:hover { border-color: var(--primary-yellow); color: var(--primary-yellow); }\n",
              "    .model-input-link {\n",
              "        background-color: var(--surface-card);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 100px;\n",
              "        padding: 8px 12px;\n",
              "        color: var(--text-primary);\n",
              "        font-family: var(--font);\n",
              "        font-size: 11px;\n",
              "        outline: none;\n",
              "        box-sizing: border-box;\n",
              "        width: 100%;\n",
              "    }\n",
              "\n",
              "    /* Header hamesha top par fixed & clickable */\n",
              "    .app-header-responsive {\n",
              "        position: relative !important;\n",
              "        z-index: 1300 !important;\n",
              "    }\n",
              "\n",
              "    /* RENDERING SCREEN (CrownTwixtor Calibrated Compact Workstation HUD) */\n",
              "    #view-rendering {\n",
              "        position: fixed !important;\n",
              "        top: 0 !important;\n",
              "        left: 0 !important;\n",
              "        width: 100% !important;\n",
              "        height: 100% !important;\n",
              "        background: var(--bg-amoled) !important;\n",
              "        z-index: 2500 !important;\n",
              "        display: none;\n",
              "        flex-direction: column;\n",
              "        align-items: center;\n",
              "        justify-content: flex-start !important;\n",
              "        padding: 12px 10px !important;\n",
              "        box-sizing: border-box !important;\n",
              "        overflow-y: auto !important;\n",
              "        overflow-x: hidden !important;\n",
              "        -webkit-overflow-scrolling: touch;\n",
              "    }\n",
              "    #view-rendering::-webkit-scrollbar { width: 4px; }\n",
              "    #view-rendering::-webkit-scrollbar-thumb { background: rgba(255, 214, 0, 0.25); border-radius: 10px; }\n",
              "    #view-rendering.active-view {\n",
              "        display: flex !important;\n",
              "        animation: slideFadeIn 0.3s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;\n",
              "    }\n",
              "\n",
              "    .modern-render-card {\n",
              "        background: var(--surface-card) !important;\n",
              "        border: 1px solid var(--border-distinct) !important;\n",
              "        border-radius: 22px !important;\n",
              "        box-shadow: var(--card-shadow) !important;\n",
              "        position: relative !important;\n",
              "        overflow: hidden !important;\n",
              "        padding: 14px 12px !important;\n",
              "        width: 100% !important;\n",
              "        max-width: 380px !important;\n",
              "        display: flex !important;\n",
              "        flex-direction: column !important;\n",
              "        align-items: center !important;\n",
              "        gap: 7px !important;\n",
              "        box-sizing: border-box !important;\n",
              "        margin: auto !important;\n",
              "        text-align: center !important;\n",
              "        flex-shrink: 0;\n",
              "    }\n",
              "    .modern-glow-bg {\n",
              "        position: absolute !important;\n",
              "        top: -40% !important; left: -40% !important; width: 180% !important; height: 180% !important;\n",
              "        background: radial-gradient(circle, var(--card-glow) 0%, transparent 60%) !important;\n",
              "        z-index: 0 !important;\n",
              "        pointer-events: none !important;\n",
              "    }\n",
              "    .modern-render-header {\n",
              "        z-index: 1;\n",
              "        width: 100%;\n",
              "        display: flex;\n",
              "        flex-direction: column;\n",
              "        align-items: center;\n",
              "        gap: 2px;\n",
              "    }\n",
              "    .pulse-icon {\n",
              "        font-size: 20px !important;\n",
              "        color: var(--primary-yellow) !important;\n",
              "        animation: floatGlow 3s ease-in-out infinite;\n",
              "    }\n",
              "    @keyframes floatGlow {\n",
              "        0%, 100% { transform: translateY(0); }\n",
              "        50% { transform: translateY(-3px); filter: drop-shadow(0 4px 8px var(--card-glow)); }\n",
              "    }\n",
              "    .render-title {\n",
              "        font-size: 13.5px !important;\n",
              "        font-weight: 800 !important;\n",
              "        color: var(--text-primary) !important;\n",
              "        margin: 0 !important;\n",
              "        white-space: nowrap !important;\n",
              "        overflow: hidden !important;\n",
              "        text-overflow: ellipsis !important;\n",
              "        max-width: 90% !important;\n",
              "    }\n",
              "    .render-subtitle {\n",
              "        font-size: 10px !important;\n",
              "        color: var(--text-muted) !important;\n",
              "    }\n",
              "\n",
              "    /* Compact File Status Card */\n",
              "    .file-status-card {\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        gap: 7px;\n",
              "        background: var(--surface-inner);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 12px;\n",
              "        padding: 5px 8px;\n",
              "        margin-top: 2px;\n",
              "        width: 100%;\n",
              "        box-sizing: border-box;\n",
              "        z-index: 1;\n",
              "    }\n",
              "    .file-status-icon {\n",
              "        width: 26px;\n",
              "        height: 26px;\n",
              "        border-radius: 7px;\n",
              "        background: var(--card-glow);\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        flex-shrink: 0;\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        color: var(--primary-yellow);\n",
              "    }\n",
              "    .file-status-icon .material-icons-round { font-size: 16px !important; }\n",
              "    .file-status-details {\n",
              "        flex: 1;\n",
              "        min-width: 0;\n",
              "        display: flex;\n",
              "        flex-direction: column;\n",
              "        gap: 1.5px;\n",
              "        text-align: left;\n",
              "    }\n",
              "    .file-status-name {\n",
              "        font-size: 11px;\n",
              "        font-weight: 700;\n",
              "        color: var(--text-primary);\n",
              "        white-space: nowrap;\n",
              "        overflow: hidden;\n",
              "        text-overflow: ellipsis;\n",
              "    }\n",
              "    .file-status-meta {\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        gap: 5px;\n",
              "        font-size: 9px;\n",
              "        font-weight: 600;\n",
              "        color: var(--text-muted);\n",
              "    }\n",
              "    .file-status-bar {\n",
              "        flex: 1;\n",
              "        height: 3.5px;\n",
              "        background: var(--surface-card);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 100px;\n",
              "        overflow: hidden;\n",
              "        min-width: 32px;\n",
              "    }\n",
              "    .file-status-fill {\n",
              "        height: 100%;\n",
              "        width: 0%;\n",
              "        background: var(--primary-yellow);\n",
              "        border-radius: 100px;\n",
              "        transition: width 0.3s ease;\n",
              "    }\n",
              "    .phase-row {\n",
              "        position: relative;\n",
              "        display: none;\n",
              "        align-items: center;\n",
              "        width: 100%;\n",
              "        max-width: 260px;\n",
              "        margin: 8px auto 2px;\n",
              "        padding: 2px;\n",
              "        box-sizing: border-box;\n",
              "        background: var(--surface-inner);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 100px;\n",
              "        overflow: hidden;\n",
              "    }\n",
              "    .phase-slider {\n",
              "        position: absolute;\n",
              "        z-index: 0;\n",
              "        top: 2px;\n",
              "        bottom: 2px;\n",
              "        left: 2px;\n",
              "        width: calc(50% - 2px);\n",
              "        border-radius: 100px;\n",
              "        background: var(--primary-yellow);\n",
              "        box-shadow: 0 2px 8px var(--card-glow);\n",
              "        transform: translateX(0);\n",
              "        transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1), width 0.4s cubic-bezier(0.22, 1, 0.36, 1);\n",
              "    }\n",
              "    .phase-row.single .phase-slider {\n",
              "        width: calc(100% - 4px);\n",
              "    }\n",
              "    .phase-row.boosting:not(.single) .phase-slider {\n",
              "        transform: translateX(100%);\n",
              "    }\n",
              "    .phase-tag {\n",
              "        position: relative;\n",
              "        z-index: 1;\n",
              "        flex: 1;\n",
              "        display: inline-flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        height: 20px;\n",
              "        padding: 0 8px;\n",
              "        border-radius: 100px;\n",
              "        background: transparent;\n",
              "        color: var(--text-muted);\n",
              "        font-size: 8.5px;\n",
              "        font-weight: 800;\n",
              "        letter-spacing: 0.35px;\n",
              "        line-height: 1;\n",
              "        box-sizing: border-box;\n",
              "        transition: color 0.3s ease;\n",
              "    }\n",
              "    .phase-tag.active {\n",
              "        color: var(--btn-text-on-accent);\n",
              "    }\n",
              "\n",
              "    .extreme-res-badge {\n",
              "        display: none;\n",
              "        align-items: center;\n",
              "        gap: 5px;\n",
              "        background: rgba(239, 68, 68, 0.1);\n",
              "        border: 1px solid rgba(239, 68, 68, 0.3);\n",
              "        color: #F87171;\n",
              "        padding: 3px 9px;\n",
              "        border-radius: 100px;\n",
              "        font-size: 9.5px;\n",
              "        font-weight: 700;\n",
              "        margin-top: 2px;\n",
              "        box-sizing: border-box;\n",
              "        text-align: center;\n",
              "        max-width: 100%;\n",
              "        z-index: 1;\n",
              "    }\n",
              "\n",
              "    /* Percentage & Progress Bar */\n",
              "    .modern-progress-wrapper {\n",
              "        z-index: 1;\n",
              "        width: 100%;\n",
              "        text-align: center;\n",
              "        margin: 1px 0;\n",
              "    }\n",
              "    .percentage-display {\n",
              "        font-size: 30px !important;\n",
              "        font-weight: 800 !important;\n",
              "        color: var(--text-primary) !important;\n",
              "        letter-spacing: -1px;\n",
              "        margin-bottom: 3px;\n",
              "        font-variant-numeric: tabular-nums;\n",
              "        line-height: 1.1;\n",
              "    }\n",
              "    .modern-bar-bg {\n",
              "        width: 100%;\n",
              "        height: 8px;\n",
              "        background: var(--surface-inner);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 100px;\n",
              "        overflow: hidden;\n",
              "        position: relative;\n",
              "        padding: 1.5px;\n",
              "        box-sizing: border-box;\n",
              "    }\n",
              "    .modern-bar-fill {\n",
              "        height: 100%;\n",
              "        width: 0%;\n",
              "        background: linear-gradient(90deg, var(--primary-yellow), var(--dark-yellow));\n",
              "        border-radius: 100px;\n",
              "        transition: width 0.25s linear;\n",
              "        position: relative;\n",
              "        overflow: hidden;\n",
              "    }\n",
              "    .modern-bar-fill::after {\n",
              "        content: \"\";\n",
              "        position: absolute;\n",
              "        top: 0; left: 0; right: 0; bottom: 0;\n",
              "        background: linear-gradient(90deg, transparent, rgba(255,255,255,0.4), transparent);\n",
              "        animation: shimmer 1.5s infinite linear;\n",
              "    }\n",
              "    @keyframes shimmer { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }\n",
              "\n",
              "    .modern-bar-fill.warmup-pulse {\n",
              "        width: 100% !important;\n",
              "        background: repeating-linear-gradient(45deg, var(--surface-inner) 0%, var(--border-distinct) 50%, var(--surface-inner) 100%) !important;\n",
              "        background-size: 200% 100% !important;\n",
              "        animation: warmup-wave 1.5s infinite linear !important;\n",
              "    }\n",
              "    @keyframes warmup-wave { 0% { background-position: 100% 0; } 100% { background-position: -100% 0; } }\n",
              "\n",
              "    /* 3-Cell Compact Stats Grid */\n",
              "    .modern-stats-grid {\n",
              "        z-index: 1;\n",
              "        width: 100%;\n",
              "        display: grid;\n",
              "        grid-template-columns: 1fr 1fr;\n",
              "        gap: 6px;\n",
              "    }\n",
              "    .modern-stat-box {\n",
              "        background: var(--surface-inner);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 12px;\n",
              "        padding: 6px 9px;\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        gap: 6px;\n",
              "        text-align: left;\n",
              "    }\n",
              "    .modern-stat-box.span-2 { grid-column: 1 / -1; }\n",
              "    .modern-stat-icon {\n",
              "        width: 26px;\n",
              "        height: 26px;\n",
              "        border-radius: 7px;\n",
              "        background: var(--card-glow);\n",
              "        color: var(--primary-yellow);\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        font-size: 13px;\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        flex-shrink: 0;\n",
              "    }\n",
              "    .modern-stat-info { display: flex; flex-direction: column; gap: 1px; min-width: 0; }\n",
              "    .stat-label { font-size: 8.5px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; }\n",
              "    .stat-value { font-size: 11px; font-weight: 700; color: var(--text-primary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n",
              "\n",
              "    /* Cancel Button & Socials */\n",
              "    .cancel-render-btn {\n",
              "        margin-top: 3px !important;\n",
              "        padding: 7px 20px !important;\n",
              "        font-size: 10px !important;\n",
              "        font-weight: 800 !important;\n",
              "        background: rgba(239, 68, 68, 0.08) !important;\n",
              "        border: 1px solid rgba(239, 68, 68, 0.35) !important;\n",
              "        color: #F87171 !important;\n",
              "        border-radius: 100px !important;\n",
              "        cursor: pointer !important;\n",
              "        text-transform: uppercase !important;\n",
              "        letter-spacing: 0.5px !important;\n",
              "        z-index: 1 !important;\n",
              "        transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1) !important;\n",
              "        box-sizing: border-box !important;\n",
              "    }\n",
              "    .cancel-render-btn:hover {\n",
              "        background: #EF4444 !important;\n",
              "        border-color: #EF4444 !important;\n",
              "        color: #FFFFFF !important;\n",
              "        box-shadow: 0 4px 16px rgba(239, 68, 68, 0.35) !important;\n",
              "        transform: translateY(-1px) !important;\n",
              "    }\n",
              "    .cancel-render-btn:active {\n",
              "        transform: scale(0.95) !important;\n",
              "        opacity: 0.9 !important;\n",
              "    }\n",
              "\n",
              "    .yt-render-tag {\n",
              "        display: inline-flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        gap: 5px;\n",
              "        background: var(--surface-inner);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        color: var(--text-primary);\n",
              "        text-decoration: none;\n",
              "        padding: 3.5px 9px;\n",
              "        border-radius: 100px;\n",
              "        font-weight: 700;\n",
              "        font-size: 9.5px;\n",
              "        transition: 0.2s;\n",
              "    }\n",
              "    .yt-render-tag:hover { border-color: var(--primary-yellow); }\n",
              "\n",
              "    /* Mobile Screen HUD Calibrations (<600px) */\n",
              "    @media (max-width: 600px) {\n",
              "        #view-rendering { padding: 8px 6px !important; }\n",
              "        .modern-render-card { padding: 12px 10px !important; gap: 6px !important; border-radius: 18px !important; max-width: 100% !important; }\n",
              "        .render-title { font-size: 13px !important; }\n",
              "        .render-subtitle { font-size: 9.5px !important; }\n",
              "        .pulse-icon { font-size: 18px !important; }\n",
              "        .file-status-card { padding: 4px 7px !important; margin-top: 1px !important; gap: 6px !important; border-radius: 10px !important; }\n",
              "        .file-status-icon { width: 22px !important; height: 22px !important; }\n",
              "        .file-status-icon .material-icons-round { font-size: 14px !important; }\n",
              "        .file-status-name { font-size: 10px !important; }\n",
              "        .percentage-display { font-size: 24px !important; margin-bottom: 2px !important; }\n",
              "        .modern-bar-bg { height: 6.5px !important; }\n",
              "        .modern-stats-grid { gap: 5px !important; }\n",
              "        .modern-stat-box { padding: 5px 7px !important; gap: 5px !important; border-radius: 10px !important; }\n",
              "        .modern-stat-icon { width: 22px !important; height: 22px !important; font-size: 12px !important; }\n",
              "        .stat-label { font-size: 8px !important; }\n",
              "        .stat-value { font-size: 10px !important; }\n",
              "        .cancel-render-btn { padding: 6px 16px !important; font-size: 9.5px !important; margin-top: 2px !important; }\n",
              "        .yt-render-tag { padding: 3px 8px !important; font-size: 9px !important; gap: 3.5px !important; }\n",
              "        .phase-row { max-width: 188px !important; margin: 5px auto 1px !important; padding: 2px !important; }\n",
              "        .phase-tag { height: 15px !important; font-size: 6.5px !important; letter-spacing: 0.15px !important; padding: 0 3px !important; }\n",
              "        .queue-card .status-chip,\n",
              "        .preview-panel .status-chip {\n",
              "            height: 15px !important;\n",
              "            font-size: 7.5px !important;\n",
              "            padding: 0 5px !important;\n",
              "        }\n",
              "        .queue-card .meta-fact,\n",
              "        .preview-panel .meta-fact {\n",
              "            font-size: 8.5px !important;\n",
              "        }\n",
              "        .queue-card .meta-sub-metrics,\n",
              "        .preview-panel .meta-sub-metrics {\n",
              "            gap: 3px 5px !important;\n",
              "        }\n",
              "    }\n",
              "\n",
              "    .queue-card {\n",
              "        background: var(--surface-card);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 16px !important;\n",
              "        padding: 8px 10px !important;\n",
              "        display: flex !important;\n",
              "        align-items: center !important;\n",
              "        gap: 10px !important;\n",
              "        box-sizing: border-box;\n",
              "        width: 100%;\n",
              "        min-width: 0;\n",
              "        position: relative;\n",
              "        transition: all 0.2s ease;\n",
              "    }\n",
              "    .queue-card:hover {\n",
              "        border-color: var(--primary-yellow);\n",
              "    }\n",
              "    .media-avatar-container {\n",
              "        position: relative;\n",
              "        width: 34px !important;\n",
              "        height: 24px !important;\n",
              "        border-radius: 6px !important;\n",
              "        overflow: hidden;\n",
              "        background: var(--surface-card);\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        flex-shrink: 0 !important;\n",
              "        cursor: pointer;\n",
              "        border: 1px solid var(--border-distinct);\n",
              "    }\n",
              "    .media-avatar-container img, .media-avatar-container video {\n",
              "        width: 100% !important;\n",
              "        height: 100% !important;\n",
              "        object-fit: cover !important;\n",
              "        pointer-events: none;\n",
              "    }\n",
              "    .queue-info-col {\n",
              "        flex: 1 1 0% !important;\n",
              "        display: flex !important;\n",
              "        flex-direction: column !important;\n",
              "        gap: 4px !important;\n",
              "        min-width: 0 !important;\n",
              "        overflow: hidden;\n",
              "    }\n",
              "    .queue-file-title {\n",
              "        font-size: 11px !important;\n",
              "        font-weight: 700 !important;\n",
              "        color: var(--text-primary);\n",
              "        white-space: nowrap !important;\n",
              "        overflow: hidden !important;\n",
              "        text-overflow: ellipsis !important;\n",
              "        cursor: pointer;\n",
              "        line-height: 1.2 !important;\n",
              "    }\n",
              "    .queue-file-title.is-marquee,\n",
              "    .preview-filename.is-marquee {\n",
              "        text-overflow: clip !important;\n",
              "    }\n",
              "    .marquee-track {\n",
              "        display: inline-flex;\n",
              "        align-items: center;\n",
              "        gap: 28px;\n",
              "        animation: cardTitleMarquee 9s linear infinite;\n",
              "        will-change: transform;\n",
              "    }\n",
              "    .marquee-track span {\n",
              "        white-space: nowrap;\n",
              "    }\n",
              "    @keyframes cardTitleMarquee {\n",
              "        from { transform: translateX(0); }\n",
              "        to { transform: translateX(calc(-50% - 14px)); }\n",
              "    }\n",
              "    .circle-icon-btn {\n",
              "        width: 22px !important;\n",
              "        height: 22px !important;\n",
              "        border-radius: 50%;\n",
              "        background: var(--surface-card);\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        cursor: pointer;\n",
              "        transition: 0.2s;\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        color: var(--text-primary);\n",
              "        flex-shrink: 0;\n",
              "    }\n",
              "    .circle-icon-btn:hover {\n",
              "        background: var(--primary-yellow);\n",
              "        color: var(--btn-text-on-accent);\n",
              "        border-color: var(--primary-yellow);\n",
              "    }\n",
              "    .circle-icon-btn .icon, .circle-icon-btn .material-icons-round {\n",
              "        font-size: 12px !important;\n",
              "    }\n",
              "    .compare-action-btn {\n",
              "        width: 22px !important;\n",
              "        height: 22px !important;\n",
              "        min-width: 22px !important;\n",
              "        min-height: 22px !important;\n",
              "        max-width: 22px !important;\n",
              "        border-radius: 50% !important;\n",
              "        background: var(--surface-card);\n",
              "        display: inline-flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        cursor: pointer;\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        color: var(--primary-yellow);\n",
              "        flex-shrink: 0;\n",
              "        padding: 0 !important;\n",
              "        box-sizing: border-box;\n",
              "        font-family: var(--font);\n",
              "        position: relative;\n",
              "        z-index: 2;\n",
              "        pointer-events: auto;\n",
              "        overflow: hidden;\n",
              "    }\n",
              "    .compare-action-btn .compare-btn-text { display: none !important; }\n",
              "    .compare-action-btn .material-icons-round { font-size: 12px !important; color: var(--primary-yellow); line-height: 1; }\n",
              "    .compare-action-btn:hover {\n",
              "        background: var(--primary-yellow);\n",
              "        border-color: var(--primary-yellow);\n",
              "    }\n",
              "    .compare-action-btn:hover .material-icons-round { color: var(--btn-text-on-accent) !important; }\n",
              "    .meta-plain {\n",
              "        font-size: 7.5px !important;\n",
              "        font-weight: 700 !important;\n",
              "        color: var(--text-secondary) !important;\n",
              "        line-height: 1 !important;\n",
              "        white-space: nowrap;\n",
              "    }\n",
              "    .queue-card .meta-sub-metrics,\n",
              "    .preview-panel .meta-sub-metrics {\n",
              "        gap: 4px 6px !important;\n",
              "        row-gap: 4px !important;\n",
              "        margin-top: 3px !important;\n",
              "    }\n",
              "    .status-chip {\n",
              "        display: inline-flex;\n",
              "        align-items: center;\n",
              "        height: 16px;\n",
              "        padding: 0 6px;\n",
              "        border-radius: 100px;\n",
              "        font-size: 8px;\n",
              "        font-weight: 800;\n",
              "        letter-spacing: 0.15px;\n",
              "        line-height: 1;\n",
              "        white-space: nowrap;\n",
              "        box-sizing: border-box;\n",
              "    }\n",
              "    .status-chip.crown {\n",
              "        color: #059669;\n",
              "        background: rgba(16, 185, 129, 0.12);\n",
              "        border: 1px solid rgba(16, 185, 129, 0.28);\n",
              "    }\n",
              "    [data-theme=\"dark\"] .status-chip.crown,\n",
              "    :root .status-chip.crown {\n",
              "        color: #34D399;\n",
              "    }\n",
              "    [data-theme=\"light\"] .status-chip.crown { color: #047857; }\n",
              "    .status-chip.twix {\n",
              "        color: var(--dark-yellow);\n",
              "        background: rgba(255, 214, 0, 0.12);\n",
              "        border: 1px solid rgba(255, 214, 0, 0.32);\n",
              "    }\n",
              "    [data-theme=\"dark\"] .status-chip.twix { color: #FFE14A; }\n",
              "    .meta-fact {\n",
              "        font-size: 9.5px;\n",
              "        font-weight: 600;\n",
              "        color: var(--text-muted);\n",
              "        letter-spacing: 0.1px;\n",
              "        line-height: 1.2;\n",
              "        white-space: nowrap;\n",
              "    }\n",
              "    @media (min-width: 768px) {\n",
              "        .queue-card .meta-sub-metrics {\n",
              "            flex-wrap: nowrap !important;\n",
              "            white-space: nowrap !important;\n",
              "        }\n",
              "        .compare-action-btn {\n",
              "            width: auto !important;\n",
              "            min-width: 78px !important;\n",
              "            max-width: none !important;\n",
              "            height: 22px !important;\n",
              "            padding: 0 10px !important;\n",
              "            border-radius: 100px !important;\n",
              "            background: var(--primary-yellow);\n",
              "            border-color: var(--primary-yellow);\n",
              "            overflow: visible;\n",
              "        }\n",
              "        .compare-action-btn .compare-btn-text {\n",
              "            display: block !important;\n",
              "            position: static;\n",
              "            padding: 0;\n",
              "            margin: 0;\n",
              "            border: none;\n",
              "            background: transparent;\n",
              "            font-size: 9px;\n",
              "            font-weight: 800;\n",
              "            letter-spacing: 0.35px;\n",
              "            line-height: 1;\n",
              "            color: #000000;\n",
              "            white-space: nowrap;\n",
              "            pointer-events: none;\n",
              "        }\n",
              "        .compare-action-btn .material-icons-round { display: none !important; }\n",
              "        .compare-action-btn:hover { filter: brightness(0.96); }\n",
              "    }\n",
              "\n",
              "    .debug-terminal { display: none; background-color: var(--surface-inner); border: 1px solid var(--highlight-cta); border-radius: 20px; padding: 16px; flex-direction: column; gap: 12px; box-sizing: border-box; width: 100%; }\n",
              "    .debug-terminal h3 { margin:0; font-size:14px; color: var(--highlight-cta); display:flex; align-items:center; gap:8px; }\n",
              "    .debug-log-text { background: var(--surface-card); padding: 12px; border-radius: 12px; font-family: monospace; font-size: 11px; color: var(--highlight-cta); overflow-x: auto; white-space: pre-wrap; max-height: 200px; border: 1px solid var(--border-distinct); }\n",
              "\n",
              "    .nav-item { display: flex; flex-direction: column; align-items: center; justify-content: center; color: var(--text-muted); cursor: pointer; gap: 4px; flex: 1; height: 100%; }\n",
              "    .nav-item .icon { font-size: 22px; }\n",
              "    .nav-item span { font-size: 11px; font-weight: 700; }\n",
              "    .nav-item.active-tab { color: var(--primary-yellow); }\n",
              "    .pill-indicator-active { background-color: var(--card-glow); padding: 4px 24px; border-radius: 100px; display: flex; align-items: center; justify-content: center; margin-bottom: 2px; border: 1px solid var(--primary-yellow); }\n",
              "\n",
              "    .interactable-node { transition: transform 0.12s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.12s ease-out !important; will-change: transform, opacity; }\n",
              "    .interactable-node:active, .node-pressed { transform: scale(0.95) !important; opacity: 0.75 !important; }\n",
              "    .queue-card:active,\n",
              "    .queue-card.node-pressed,\n",
              "    .queue-card.interactable-node:active {\n",
              "        transform: none !important;\n",
              "        opacity: 1 !important;\n",
              "    }\n",
              "    .queue-card .circle-icon-btn {\n",
              "        position: relative;\n",
              "        z-index: 2;\n",
              "        pointer-events: auto;\n",
              "    }\n",
              "\n",
              "    .modal-backdrop {\n",
              "        position: fixed;\n",
              "        top: 0; bottom: 0; left: 0; right: 0;\n",
              "        background-color: rgba(0, 0, 0, 0.75);\n",
              "        backdrop-filter: blur(6px);\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        z-index: 2000;\n",
              "        opacity: 0;\n",
              "        pointer-events: none;\n",
              "        transition: opacity 0.2s ease;\n",
              "        touch-action: none !important;\n",
              "        overscroll-behavior: contain !important;\n",
              "    }\n",
              "    .modal-backdrop.show {\n",
              "        opacity: 1;\n",
              "        pointer-events: auto;\n",
              "    }\n",
              "    /* Modal open hone par background page ko freeze/lock karega */\n",
              "    body:has(.modal-backdrop.show) .studio-canvas,\n",
              "    body:has(.modal-backdrop.show) {\n",
              "        overflow: hidden !important;\n",
              "    }\n",
              "    .modal-backdrop:not(#mediaPreviewModal) .modal-card {\n",
              "        background-color: var(--modal-bg);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 22px !important;\n",
              "        padding: 18px 16px !important;\n",
              "        width: 86%;\n",
              "        max-width: 300px;\n",
              "        display: flex;\n",
              "        flex-direction: column;\n",
              "        gap: 14px !important;\n",
              "        box-shadow: var(--card-shadow) !important;\n",
              "        box-sizing: border-box;\n",
              "        text-align: center;\n",
              "        touch-action: auto;\n",
              "    }\n",
              "    .modal-card {\n",
              "        background-color: var(--modal-bg);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 22px;\n",
              "        padding: 18px 16px;\n",
              "        width: 86%;\n",
              "        max-width: 300px;\n",
              "        display: flex;\n",
              "        flex-direction: column;\n",
              "        gap: 14px;\n",
              "        box-shadow: var(--card-shadow);\n",
              "        box-sizing: border-box;\n",
              "        text-align: center;\n",
              "        touch-action: auto;\n",
              "    }\n",
              "    .modal-title { font-size: 13.5px; font-weight: 800; margin: 0; color: var(--text-primary); letter-spacing: -0.2px; text-align: center; }\n",
              "    .modal-card p { color: var(--text-secondary) !important; font-size: 12px !important; line-height: 1.45 !important; margin: 0 !important; }\n",
              "    .modal-input-row { display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; box-sizing: border-box; }\n",
              "    .modal-field { flex: 1; min-width: 0; background-color: var(--input-bg); border: 1px solid var(--border-distinct); border-radius: 12px; padding: 10px 8px; color: var(--text-primary); text-align: center; font-family: var(--font); font-size: 13px; font-weight: 700; outline: none; box-sizing: border-box; }\n",
              "    .modal-field:focus { border-color: var(--primary-yellow); box-shadow: 0 0 0 3px var(--card-glow); }\n",
              "    .modal-divider { color: var(--text-secondary); font-weight: 700; font-size: 13px; }\n",
              "    .modal-actions { display: flex; gap: 10px; justify-content: center; margin-top: 4px; width: 100%; }\n",
              "    .modal-backdrop:not(#mediaPreviewModal) .modal-btn { min-height: 36px !important; padding: 10px 14px !important; font-size: 11px !important; }\n",
              "    .modal-btn { min-height: 36px; padding: 10px 14px; border-radius: 100px; font-family: var(--font); font-size: 11px; font-weight: 800; border: none; cursor: pointer; flex: 1; text-align: center; box-sizing: border-box; text-transform: uppercase; letter-spacing: 0.3px; }\n",
              "    .modal-btn.save { background-color: var(--primary-yellow); color: var(--btn-text-on-accent); box-shadow: 0 6px 16px var(--card-glow); }\n",
              "    .modal-btn.cancel { background-color: var(--surface-inner); border: 1px solid var(--border-distinct); color: var(--text-primary); }\n",
              "\n",
              "    /* Desktop Overlay Scaling (min-width: 768px) */\n",
              "    @media (min-width: 768px) {\n",
              "        .modal-card {\n",
              "            max-width: 380px !important;\n",
              "            padding: 22px 20px !important;\n",
              "            border-radius: 24px !important;\n",
              "            gap: 14px !important;\n",
              "        }\n",
              "        .modal-title {\n",
              "            font-size: 15px !important;\n",
              "        }\n",
              "        .modal-field {\n",
              "            font-size: 13px !important;\n",
              "            padding: 10px 12px !important;\n",
              "            border-radius: 12px !important;\n",
              "        }\n",
              "        .modal-divider {\n",
              "            font-size: 15px !important;\n",
              "        }\n",
              "        .modal-actions {\n",
              "            gap: 10px !important;\n",
              "            margin-top: 6px !important;\n",
              "        }\n",
              "        .modal-btn {\n",
              "            padding: 10px 16px !important;\n",
              "            font-size: 12px !important;\n",
              "        }\n",
              "        #mediaPreviewModal .modal-card {\n",
              "            width: min(1120px, 96%) !important;\n",
              "            max-width: min(1120px, 96%) !important;\n",
              "            min-height: calc(var(--app-viewport-h) - 28px) !important;\n",
              "            max-height: calc(var(--app-viewport-h) - 16px) !important;\n",
              "            padding: 12px 14px !important;\n",
              "            gap: 10px !important;\n",
              "            border-radius: 18px !important;\n",
              "        }\n",
              "        #downloadOverlay {\n",
              "            max-width: 360px !important;\n",
              "            bottom: 80px !important;\n",
              "            right: 20px !important;\n",
              "            padding: 14px 16px !important;\n",
              "            border-radius: 20px !important;\n",
              "        }\n",
              "        #downloadOverlay .dl-overlay-title {\n",
              "            font-size: 13px !important;\n",
              "        }\n",
              "        #downloadOverlay .dl-item-name {\n",
              "            font-size: 12px !important;\n",
              "        }\n",
              "        #downloadOverlay .dl-item-meta {\n",
              "            font-size: 10.5px !important;\n",
              "        }\n",
              "    }\n",
              "\n",
              "    .empty-state {\n",
              "        padding: 40px 16px;\n",
              "        text-align: center;\n",
              "        color: var(--text-muted);\n",
              "        font-size: 14px;\n",
              "        font-weight: 600;\n",
              "        background: var(--surface-card);\n",
              "        border: 1px dashed var(--border-distinct);\n",
              "        border-radius: 20px;\n",
              "        margin-top: 12px;\n",
              "        position: relative;\n",
              "        overflow: hidden;\n",
              "    }\n",
              "    .empty-state .material-icons-round {\n",
              "        color: var(--text-muted);\n",
              "        font-size: 40px !important;\n",
              "        margin-bottom: 8px;\n",
              "    }\n",
              "\n",
              "    /* COMPACT VERTICAL LAYOUT FOR MOBILE SCREENS (CrownTwixtor Calibrated) */\n",
              "    @media (max-width: 600px) {\n",
              "        .studio-canvas {\n",
              "            padding: 6px 5px !important;\n",
              "            padding-bottom: 70px !important;\n",
              "            gap: 8px !important;\n",
              "        }\n",
              "        .app-header-responsive {\n",
              "            padding: 6px 10px !important;\n",
              "            border-radius: 18px !important;\n",
              "            min-height: 42px !important;\n",
              "            gap: 6px !important;\n",
              "            margin-bottom: 3px !important;\n",
              "        }\n",
              "        .header-brand-wrap img {\n",
              "            width: 24px !important;\n",
              "            height: 24px !important;\n",
              "        }\n",
              "        .app-title-main {\n",
              "            font-size: 12.5px !important;\n",
              "            white-space: nowrap !important;\n",
              "        }\n",
              "        .compose-card {\n",
              "            padding: 9px 11px !important;\n",
              "            gap: 7px !important;\n",
              "            border-radius: 20px !important;\n",
              "        }\n",
              "        .upload-box {\n",
              "            padding: 13px 6px !important;\n",
              "            border-radius: 18px !important;\n",
              "        }\n",
              "        .upload-circle {\n",
              "            width: 32px !important;\n",
              "            height: 32px !important;\n",
              "            margin-bottom: 3px !important;\n",
              "        }\n",
              "        .upload-circle .icon {\n",
              "            font-size: 17px !important;\n",
              "        }\n",
              "        .upload-title {\n",
              "            font-size: 12px !important;\n",
              "            margin-bottom: 1px !important;\n",
              "        }\n",
              "        .upload-subtitle {\n",
              "            font-size: 10px !important;\n",
              "        }\n",
              "        .action-button-main {\n",
              "            padding: 12px 18px !important;\n",
              "            font-size: 12px !important;\n",
              "            margin: 4px 0 !important;\n",
              "            border-radius: 100px !important;\n",
              "            min-height: 42px !important;\n",
              "        }\n",
              "        .dashboard-layout {\n",
              "            gap: 8px !important;\n",
              "        }\n",
              "        .selectable-chip {\n",
              "            padding: 5px 12px !important;\n",
              "            font-size: 11px !important;\n",
              "        }\n",
              "        .block-selector {\n",
              "            padding: 6px 4px !important;\n",
              "            font-size: 11px !important;\n",
              "        }\n",
              "        .range-container {\n",
              "            padding: 1px 0 !important;\n",
              "        }\n",
              "        .range-input {\n",
              "            height: 20px !important;\n",
              "            touch-action: pan-x !important;\n",
              "        }\n",
              "        .range-input::-webkit-slider-runnable-track {\n",
              "            height: 4px !important;\n",
              "        }\n",
              "        .range-input::-webkit-slider-thumb {\n",
              "            width: 16px !important;\n",
              "            height: 16px !important;\n",
              "            margin-top: -6.5px !important;\n",
              "        }\n",
              "        .range-input::-moz-range-thumb {\n",
              "            width: 15px !important;\n",
              "            height: 15px !important;\n",
              "        }\n",
              "        .switch-row {\n",
              "            padding: 1px 0 !important;\n",
              "            gap: 5px !important;\n",
              "        }\n",
              "        .switch-widget {\n",
              "            width: 28px !important;\n",
              "            height: 16px !important;\n",
              "        }\n",
              "        .switch-slider {\n",
              "            border-radius: 30px !important;\n",
              "        }\n",
              "        .switch-slider:before {\n",
              "            height: 10px !important;\n",
              "            width: 10px !important;\n",
              "            left: 2px !important;\n",
              "            bottom: 2px !important;\n",
              "        }\n",
              "        input:checked + .switch-slider:before {\n",
              "            transform: translateX(12px) !important;\n",
              "        }\n",
              "        .component-title {\n",
              "            font-size: 11px !important;\n",
              "        }\n",
              "        .badge-pills {\n",
              "            font-size: 11px !important;\n",
              "        }\n",
              "        .slider-labels {\n",
              "            font-size: 9.5px !important;\n",
              "        }\n",
              "        .preview-panel, .queue-card {\n",
              "            padding: 7px 8px !important;\n",
              "            gap: 8px !important;\n",
              "            border-radius: 14px !important;\n",
              "        }\n",
              "        .preview-media-container, .media-avatar-container {\n",
              "            width: 34px !important;\n",
              "            height: 24px !important;\n",
              "            border-radius: 7px !important;\n",
              "        }\n",
              "        .preview-filename, .queue-file-title {\n",
              "            font-size: 9.5px !important;\n",
              "            font-weight: 600 !important;\n",
              "            letter-spacing: -0.15px !important;\n",
              "            line-height: 1.2 !important;\n",
              "        }\n",
              "        .meta-sub-metrics {\n",
              "            font-size: 8px !important;\n",
              "        }\n",
              "        .circle-icon-btn,\n",
              "        .compare-action-btn {\n",
              "            width: 23px !important;\n",
              "            height: 23px !important;\n",
              "            min-width: 23px !important;\n",
              "            min-height: 23px !important;\n",
              "            max-width: 23px !important;\n",
              "        }\n",
              "        .circle-icon-btn .icon,\n",
              "        .compare-action-btn .material-icons-round {\n",
              "            font-size: 12px !important;\n",
              "        }\n",
              "        .bottom-navbar {\n",
              "            height: 50px !important;\n",
              "            padding: 0 10px !important;\n",
              "        }\n",
              "        .bottom-navbar .icon {\n",
              "            font-size: 17px !important;\n",
              "        }\n",
              "        .bottom-navbar span {\n",
              "            font-size: 9.5px !important;\n",
              "        }\n",
              "        .pill-indicator-active {\n",
              "            padding: 3px 16px !important;\n",
              "        }\n",
              "    }\n",
              "\n",
              "    @media (max-width: 480px) {\n",
              "        .studio-canvas {\n",
              "            padding: 5px 4px !important;\n",
              "            padding-bottom: 68px !important;\n",
              "        }\n",
              "        .app-header-responsive {\n",
              "            padding: 5px 8px !important;\n",
              "            border-radius: 16px !important;\n",
              "            gap: 4px !important;\n",
              "        }\n",
              "        .header-brand-wrap img {\n",
              "            width: 22px !important;\n",
              "            height: 22px !important;\n",
              "        }\n",
              "        .app-title-main {\n",
              "            font-size: 12px !important;\n",
              "        }\n",
              "        .header-social-capsule {\n",
              "            display: flex !important;\n",
              "            padding: 1px 3px !important;\n",
              "            gap: 1.5px !important;\n",
              "        }\n",
              "        .social-symbol {\n",
              "            width: 18px !important;\n",
              "            height: 18px !important;\n",
              "        }\n",
              "        .social-symbol.yt i, .social-symbol.dc i, .social-symbol.wb i {\n",
              "            font-size: 9px !important;\n",
              "        }\n",
              "        .header-action-btn {\n",
              "            width: 22px !important;\n",
              "            height: 22px !important;\n",
              "        }\n",
              "        .header-action-btn span {\n",
              "            font-size: 12px !important;\n",
              "        }\n",
              "    }\n",
              "\n",
              "    /* COMPARISON PREVIEW MODAL STYLES */\n",
              "    #mediaPreviewModal .modal-card {\n",
              "        max-width: 95%;\n",
              "        max-height: 88vh;\n",
              "        width: 100%;\n",
              "        padding: 16px;\n",
              "        background: var(--surface-card);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        box-shadow: var(--card-shadow);\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        flex-direction: column;\n",
              "        gap: 12px;\n",
              "        position: relative;\n",
              "    }\n",
              "    #fullMediaContainer {\n",
              "        width: 100%;\n",
              "        min-height: 240px;\n",
              "        max-height: 75vh;\n",
              "        display: flex;\n",
              "        justify-content: center;\n",
              "        align-items: center;\n",
              "        position: relative;\n",
              "        overflow: hidden;\n",
              "        border-radius: 18px;\n",
              "    }\n",
              "    .preview-loading {\n",
              "        position: absolute;\n",
              "        inset: 0;\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        background: rgba(11, 12, 16, 0.55);\n",
              "        z-index: 40;\n",
              "        border-radius: 16px;\n",
              "        pointer-events: none;\n",
              "    }\n",
              "    .preview-loading .md3-spinner {\n",
              "        width: 42px;\n",
              "        height: 42px;\n",
              "        margin: 0;\n",
              "    }\n",
              "    .preview-media-fit {\n",
              "        width: auto !important;\n",
              "        height: auto !important;\n",
              "        max-width: 100%;\n",
              "        max-height: 70vh;\n",
              "        border-radius: 16px;\n",
              "        outline: none;\n",
              "        background: #000;\n",
              "        box-shadow: var(--card-shadow);\n",
              "        object-fit: contain;\n",
              "    }\n",
              "    @media (min-width: 768px) {\n",
              "        #fullMediaContainer {\n",
              "            width: 100%;\n",
              "            height: calc(var(--app-viewport-h) - 96px);\n",
              "            min-height: calc(var(--app-viewport-h) - 96px);\n",
              "            max-height: calc(var(--app-viewport-h) - 96px);\n",
              "        }\n",
              "        .compare-stage {\n",
              "            width: 100% !important;\n",
              "            height: 100% !important;\n",
              "            min-height: 100% !important;\n",
              "            max-width: 100%;\n",
              "            max-height: 100%;\n",
              "        }\n",
              "        .compare-stage img, .compare-stage video,\n",
              "        .preview-media-fit {\n",
              "            width: 100% !important;\n",
              "            height: 100% !important;\n",
              "            max-width: 100%;\n",
              "            max-height: 100% !important;\n",
              "        }\n",
              "    }\n",
              "\n",
              "    .compare-stage {\n",
              "        position: relative;\n",
              "        width: auto;\n",
              "        height: auto;\n",
              "        max-width: 100%;\n",
              "        max-height: 75vh;\n",
              "        overflow: hidden;\n",
              "        user-select: none;\n",
              "        touch-action: none;\n",
              "        border-radius: 16px;\n",
              "        background: #000000;\n",
              "        display: inline-flex;\n",
              "    }\n",
              "    .compare-stage img, .compare-stage video {\n",
              "        display: block;\n",
              "        width: auto !important;\n",
              "        height: auto !important;\n",
              "        max-width: 100%;\n",
              "        max-height: 75vh;\n",
              "        object-fit: contain;\n",
              "    }\n",
              "    @media (min-width: 768px) {\n",
              "        .compare-stage {\n",
              "            width: 100% !important;\n",
              "            height: 100% !important;\n",
              "            min-height: 100% !important;\n",
              "        }\n",
              "        .compare-stage img,\n",
              "        .compare-stage video,\n",
              "        .preview-media-fit {\n",
              "            width: 100% !important;\n",
              "            height: 100% !important;\n",
              "            max-width: 100% !important;\n",
              "            max-height: 100% !important;\n",
              "            object-fit: contain;\n",
              "        }\n",
              "    }\n",
              "    .compare-overlay {\n",
              "        position: absolute;\n",
              "        top: 0;\n",
              "        left: 0;\n",
              "        width: 100%;\n",
              "        height: 100%;\n",
              "        overflow: hidden;\n",
              "        pointer-events: none;\n",
              "        clip-path: polygon(0 0, 50% 0, 50% 100%, 0 100%);\n",
              "    }\n",
              "    .compare-overlay img, .compare-overlay video {\n",
              "        position: absolute;\n",
              "        top: 0;\n",
              "        left: 0;\n",
              "        width: 100% !important;\n",
              "        height: 100% !important;\n",
              "        object-fit: contain;\n",
              "    }\n",
              "    .compare-handle-line {\n",
              "        position: absolute;\n",
              "        top: 0;\n",
              "        bottom: 0;\n",
              "        left: 50%;\n",
              "        width: 3px;\n",
              "        background: var(--primary-yellow);\n",
              "        box-shadow: 0 0 12px rgba(0, 0, 0, 0.8), 0 0 8px var(--primary-yellow);\n",
              "        transform: translateX(-50%);\n",
              "        pointer-events: none;\n",
              "        z-index: 20;\n",
              "    }\n",
              "    .compare-handle-btn {\n",
              "        position: absolute;\n",
              "        top: 50%;\n",
              "        left: 50%;\n",
              "        transform: translate(-50%, -50%);\n",
              "        width: 36px;\n",
              "        height: 36px;\n",
              "        border-radius: 50%;\n",
              "        background: var(--primary-yellow);\n",
              "        color: #000000;\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        box-shadow: 0 4px 14px rgba(0,0,0,0.6);\n",
              "        border: 2px solid #FFFFFF;\n",
              "        cursor: ew-resize;\n",
              "        pointer-events: auto;\n",
              "        z-index: 25;\n",
              "    }\n",
              "    .compare-label {\n",
              "        position: absolute;\n",
              "        top: 12px;\n",
              "        padding: 4px 10px;\n",
              "        border-radius: 100px;\n",
              "        font-size: 10px;\n",
              "        font-weight: 800;\n",
              "        letter-spacing: 0.5px;\n",
              "        z-index: 15;\n",
              "        pointer-events: none;\n",
              "        backdrop-filter: blur(4px);\n",
              "    }\n",
              "    .compare-label.left {\n",
              "        left: 12px;\n",
              "        background: rgba(0, 0, 0, 0.65);\n",
              "        color: #FFFFFF;\n",
              "        border: 1px solid rgba(255, 255, 255, 0.3);\n",
              "    }\n",
              "    .compare-label.right {\n",
              "        right: 12px;\n",
              "        background: rgba(255, 214, 0, 0.85);\n",
              "        color: #000000;\n",
              "        border: 1px solid var(--primary-yellow);\n",
              "    }\n",
              "\n",
              "    .file-status-card {\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        gap: 12px;\n",
              "        background: var(--surface-inner);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 16px;\n",
              "        padding: 10px 16px;\n",
              "        margin-top: 10px;\n",
              "        width: 100%;\n",
              "        max-width: 340px;\n",
              "        box-sizing: border-box;\n",
              "        transition: all 0.3s ease;\n",
              "    }\n",
              "\n",
              "    .file-status-icon {\n",
              "        width: 36px;\n",
              "        height: 36px;\n",
              "        border-radius: 10px;\n",
              "        background: var(--card-glow);\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        justify-content: center;\n",
              "        flex-shrink: 0;\n",
              "        border: 1px solid var(--border-distinct);\n",
              "    }\n",
              "    .file-status-icon .material-icons-round {\n",
              "        font-size: 20px;\n",
              "        color: var(--primary-yellow);\n",
              "    }\n",
              "    .file-status-details {\n",
              "        flex: 1;\n",
              "        min-width: 0;\n",
              "        display: flex;\n",
              "        flex-direction: column;\n",
              "        gap: 4px;\n",
              "    }\n",
              "    .file-status-name {\n",
              "        font-size: 13px;\n",
              "        font-weight: 700;\n",
              "        color: var(--text-primary);\n",
              "        white-space: nowrap;\n",
              "        overflow: hidden;\n",
              "        text-overflow: ellipsis;\n",
              "    }\n",
              "    .file-status-meta {\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        gap: 8px;\n",
              "        font-size: 11px;\n",
              "        font-weight: 600;\n",
              "        color: var(--text-muted);\n",
              "    }\n",
              "    .file-status-bar {\n",
              "        flex: 1;\n",
              "        height: 4px;\n",
              "        background: var(--surface-card);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 100px;\n",
              "        overflow: hidden;\n",
              "        min-width: 40px;\n",
              "    }\n",
              "    .file-status-fill {\n",
              "        height: 100%;\n",
              "        width: 0%;\n",
              "        background: var(--primary-yellow);\n",
              "        border-radius: 100px;\n",
              "        transition: width 0.4s ease;\n",
              "    }\n",
              "    .upload-box > * {\n",
              "      pointer-events: none;\n",
              "    }\n",
              "\n",
              "    .extreme-res-badge {\n",
              "        display: none;\n",
              "        align-items: center;\n",
              "        gap: 6px;\n",
              "        background: rgba(239, 68, 68, 0.12);\n",
              "        border: 1px solid rgba(239, 68, 68, 0.35);\n",
              "        color: #F87171;\n",
              "        padding: 6px 14px;\n",
              "        border-radius: 100px;\n",
              "        font-size: 11px;\n",
              "        font-weight: 700;\n",
              "        margin-top: 10px;\n",
              "        animation: pulse-border 2s infinite ease-in-out;\n",
              "        box-sizing: border-box;\n",
              "        text-align: center;\n",
              "        max-width: 340px;\n",
              "    }\n",
              "    @keyframes pulse-border {\n",
              "        0%, 100% { border-color: rgba(239, 68, 68, 0.35); }\n",
              "        50% { border-color: rgba(239, 68, 68, 0.8); }\n",
              "    }\n",
              "\n",
              "    #downloadOverlay {\n",
              "        position: fixed;\n",
              "        bottom: 70px;\n",
              "        right: 14px;\n",
              "        width: calc(100% - 28px);\n",
              "        max-width: 330px;\n",
              "        background: var(--surface-card);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 18px;\n",
              "        box-shadow: var(--card-shadow);\n",
              "        z-index: 1500;\n",
              "        display: none;\n",
              "        flex-direction: column;\n",
              "        padding: 11px 13px;\n",
              "        box-sizing: border-box;\n",
              "        gap: 7px;\n",
              "        max-height: 340px;\n",
              "        overflow: hidden;\n",
              "        animation: slideFadeIn 0.3s ease forwards;\n",
              "    }\n",
              "    .dl-overlay-header {\n",
              "        display: flex;\n",
              "        justify-content: space-between;\n",
              "        align-items: center;\n",
              "        border-bottom: 1px solid var(--border-distinct);\n",
              "        padding-bottom: 8px;\n",
              "    }\n",
              "    .dl-overlay-title {\n",
              "        font-size: 13px;\n",
              "        font-weight: 800;\n",
              "        color: var(--text-primary);\n",
              "        display: flex;\n",
              "        align-items: center;\n",
              "        gap: 6px;\n",
              "    }\n",
              "    .dl-overlay-badge {\n",
              "        background: var(--primary-yellow);\n",
              "        color: var(--btn-text-on-accent);\n",
              "        font-size: 10px;\n",
              "        font-weight: 800;\n",
              "        padding: 2px 6px;\n",
              "        border-radius: 100px;\n",
              "    }\n",
              "    .dl-overlay-list {\n",
              "        display: flex;\n",
              "        flex-direction: column;\n",
              "        gap: 8px;\n",
              "        overflow-y: auto;\n",
              "        max-height: 280px;\n",
              "        padding-right: 2px;\n",
              "    }\n",
              "    .dl-overlay-list::-webkit-scrollbar { width: 4px; }\n",
              "    .dl-overlay-list::-webkit-scrollbar-thumb { background: var(--border-distinct); border-radius: 4px; }\n",
              "\n",
              "    .dl-item-card {\n",
              "        background: var(--surface-inner);\n",
              "        border: 1px solid var(--border-distinct);\n",
              "        border-radius: 14px;\n",
              "        padding: 8px 10px;\n",
              "        display: flex;\n",
              "        flex-direction: column;\n",
              "        gap: 6px;\n",
              "        position: relative;\n",
              "    }\n",
              "    .dl-item-top {\n",
              "        display: flex;\n",
              "        justify-content: space-between;\n",
              "        align-items: center;\n",
              "        gap: 8px;\n",
              "    }\n",
              "    .dl-item-name {\n",
              "        font-size: 12px;\n",
              "        font-weight: 700;\n",
              "        color: var(--text-primary);\n",
              "        white-space: nowrap;\n",
              "        overflow: hidden;\n",
              "        text-overflow: ellipsis;\n",
              "        flex: 1;\n",
              "    }\n",
              "    .dl-item-cancel {\n",
              "        color: var(--text-muted);\n",
              "        cursor: pointer;\n",
              "        font-size: 16px;\n",
              "        transition: 0.2s;\n",
              "        flex-shrink: 0;\n",
              "    }\n",
              "    .dl-item-cancel:hover { color: var(--highlight-cta); }\n",
              "    .dl-item-bar {\n",
              "        width: 100%;\n",
              "        height: 4px;\n",
              "        background: var(--surface-card);\n",
              "        border-radius: 100px;\n",
              "        overflow: hidden;\n",
              "        border: 1px solid var(--border-distinct);\n",
              "    }\n",
              "    .dl-item-fill {\n",
              "        height: 100%;\n",
              "        width: 0%;\n",
              "        background: var(--primary-yellow);\n",
              "        border-radius: 100px;\n",
              "        transition: width 0.15s linear;\n",
              "    }\n",
              "    .dl-item-meta {\n",
              "        display: flex;\n",
              "        justify-content: space-between;\n",
              "        align-items: center;\n",
              "        font-size: 10px;\n",
              "        font-weight: 600;\n",
              "        color: var(--text-muted);\n",
              "    }\n",
              "</style>\n",
              "</head>\n",
              "<body style=\"position:relative; min-height:100vh;\">\n",
              "\n",
              "<div class=\"wm-target\" style=\"position: fixed; bottom: 70px; right: 14px; background: var(--surface-card); border: 1px solid var(--primary-yellow); padding: 4px 10px; border-radius: 100px; font-size: 9.5px; font-weight: 800; color: var(--primary-yellow); z-index: 500; pointer-events: none; opacity: 0.85; letter-spacing: 0.8px; box-shadow: var(--card-shadow);\"></div>\n",
              "\n",
              "<!-- DOWNLOAD MANAGER OVERLAY -->\n",
              "<div id=\"downloadOverlay\">\n",
              "    <div class=\"dl-overlay-header\">\n",
              "        <div class=\"dl-overlay-title\">\n",
              "            <span class=\"material-icons-round\" style=\"font-size: 16px; color: var(--primary-yellow);\">download</span>\n",
              "            Downloads\n",
              "            <span class=\"dl-overlay-badge\" id=\"dlActiveCount\">0</span>\n",
              "        </div>\n",
              "    </div>\n",
              "    <div class=\"dl-overlay-list\" id=\"dlOverlayList\"></div>\n",
              "</div>\n",
              "\n",
              "<div id=\"startupLoader\" onclick=\"handleUserWakeTap()\" style=\"cursor: pointer; /*__LOADER_STYLE__*/\">\n",
              "    <svg class=\"md3-spinner\" viewBox=\"0 0 50 50\"><circle cx=\"25\" cy=\"25\" r=\"20\"></circle></svg>\n",
              "    <div class=\"loader-title\" id=\"loaderTitleText\">Setting Up CrownScaler</div>\n",
              "    <div class=\"loader-subtitle\" id=\"loaderSubtitleText\" style=\"margin-bottom: 8px;\">Preparing environment & dependencies (~1-2 mins on first run)...</div>\n",
              "\n",
              "    <div id=\"loaderHintText\" style=\"font-size: 13px; color: var(--text-primary); margin-bottom: 20px; font-weight: 700; text-align: center; opacity: 1;\">\n",
              "        <span id=\"firstRunNotice\" style=\"color: var(--text-muted); font-weight: 600;\">Downloading Neural Core & TensorRT (First run only)<br><br></span>\n",
              "        <span id=\"reconnectInstruction\" style=\"display: none;\">Please click Play button again if it's not reconnecting.<br><br></span>\n",
              "        <span id=\"awakePromptBadge\" style=\"display: inline-flex; align-items: center; justify-content: center; gap: 6px; color: var(--primary-yellow); background: var(--card-glow); font-size: 12px; font-weight: 700; padding: 8px 18px; border: 1px dashed var(--primary-yellow); border-radius: 100px; margin-top: 4px; cursor: pointer; transition: all 0.2s ease;\">\n",
              "            <span class=\"material-icons-round\" style=\"font-size: 16px;\">touch_app</span>\n",
              "            Tap anywhere to keep screen awake\n",
              "        </span>\n",
              "    </div>\n",
              "\n",
              "    <div id=\"loaderPercentage\" style=\"font-size: 38px; font-weight: 800; color: var(--primary-yellow); letter-spacing: -1px; margin-bottom: 8px; font-variant-numeric: tabular-nums;\">0%</div>\n",
              "\n",
              "    <div class=\"wavy-progress-bg\"><div class=\"wavy-progress-fill\"></div></div>\n",
              "    <div class=\"loader-timer\" id=\"loaderTimer\" style=\"margin-top: 6px;\">00:00</div>\n",
              "</div>\n",
              "\n",
              "<div class=\"studio-canvas\" id=\"mainApp\" style=\"/*__APP_STYLE__*/\">\n",
              "<!-- Header with Theme Toggle Button (CrownTwixtor Calibrated) -->\n",
              "    <style>\n",
              "        .app-header-responsive {\n",
              "            background: var(--surface-card);\n",
              "            border: 1px solid var(--border-distinct);\n",
              "            border-radius: 20px;\n",
              "            padding: 7px 12px;\n",
              "            margin-bottom: 4px;\n",
              "            display: flex;\n",
              "            justify-content: space-between;\n",
              "            align-items: center;\n",
              "            box-shadow: var(--card-shadow);\n",
              "            box-sizing: border-box;\n",
              "            width: 100%;\n",
              "            gap: 6px;\n",
              "            min-height: 46px;\n",
              "        }\n",
              "        .header-brand-wrap {\n",
              "            display: flex;\n",
              "            align-items: center;\n",
              "            gap: 7px;\n",
              "            text-decoration: none;\n",
              "            flex-shrink: 0;\n",
              "            min-width: 0;\n",
              "        }\n",
              "        .header-brand-wrap img {\n",
              "            width: 28px;\n",
              "            height: 28px;\n",
              "            border-radius: 50%;\n",
              "            object-fit: cover;\n",
              "            border: 1.5px solid var(--primary-yellow);\n",
              "            box-shadow: 0 2px 6px var(--card-glow);\n",
              "            flex-shrink: 0;\n",
              "        }\n",
              "        .app-title-main {\n",
              "            font-size: 14px;\n",
              "            font-weight: 800;\n",
              "            letter-spacing: -0.3px;\n",
              "            margin: 0;\n",
              "            color: var(--text-primary);\n",
              "            white-space: nowrap;\n",
              "        }\n",
              "        .header-right-capsule {\n",
              "            display: flex;\n",
              "            align-items: center;\n",
              "            gap: 5px;\n",
              "            flex-shrink: 0;\n",
              "            margin-left: auto;\n",
              "        }\n",
              "        .header-social-capsule {\n",
              "            display: flex;\n",
              "            gap: 2px;\n",
              "            background: var(--surface-inner);\n",
              "            padding: 2px 5px;\n",
              "            border-radius: 100px;\n",
              "            border: 1px solid var(--border-distinct);\n",
              "            align-items: center;\n",
              "            flex-shrink: 0;\n",
              "        }\n",
              "        .social-symbol {\n",
              "            display: flex;\n",
              "            align-items: center;\n",
              "            justify-content: center;\n",
              "            width: 22px;\n",
              "            height: 22px;\n",
              "            border-radius: 50%;\n",
              "            color: var(--text-muted);\n",
              "            text-decoration: none;\n",
              "            transition: 0.2s;\n",
              "            flex-shrink: 0;\n",
              "        }\n",
              "        .social-symbol:hover { color: var(--text-primary); }\n",
              "        .social-symbol.yt i { color: #FF0000; font-size: 11px; }\n",
              "        .social-symbol.dc i { color: #5865F2; font-size: 11px; }\n",
              "        .social-symbol.wb i { color: var(--primary-yellow); font-size: 11px; }\n",
              "\n",
              "        .header-right-capsule .circle-icon-btn {\n",
              "            width: 26px !important;\n",
              "            height: 26px !important;\n",
              "            flex-shrink: 0;\n",
              "        }\n",
              "\n",
              "        @media (max-width: 600px) {\n",
              "            .app-header-responsive {\n",
              "                padding: 6px 10px !important;\n",
              "                border-radius: 18px !important;\n",
              "                min-height: 42px !important;\n",
              "                gap: 6px !important;\n",
              "                margin-bottom: 3px !important;\n",
              "            }\n",
              "            .header-brand-wrap img {\n",
              "                width: 24px !important;\n",
              "                height: 24px !important;\n",
              "            }\n",
              "            .app-title-main {\n",
              "                font-size: 12.5px !important;\n",
              "            }\n",
              "        }\n",
              "        @media (max-width: 480px) {\n",
              "            .app-header-responsive {\n",
              "                padding: 5px 8px !important;\n",
              "                border-radius: 16px !important;\n",
              "                gap: 4px !important;\n",
              "            }\n",
              "            .header-brand-wrap img {\n",
              "                width: 22px !important;\n",
              "                height: 22px !important;\n",
              "            }\n",
              "            .app-title-main {\n",
              "                font-size: 12px !important;\n",
              "            }\n",
              "            .header-social-capsule {\n",
              "                display: flex !important;\n",
              "                padding: 1px 3px !important;\n",
              "                gap: 1.5px !important;\n",
              "            }\n",
              "            .social-symbol {\n",
              "                width: 18px !important;\n",
              "                height: 18px !important;\n",
              "            }\n",
              "            .social-symbol.yt i, .social-symbol.dc i, .social-symbol.wb i {\n",
              "                font-size: 9px !important;\n",
              "            }\n",
              "            .header-right-capsule .circle-icon-btn {\n",
              "                width: 22px !important;\n",
              "                height: 22px !important;\n",
              "            }\n",
              "            .header-right-capsule .circle-icon-btn span {\n",
              "                font-size: 12px !important;\n",
              "            }\n",
              "        }\n",
              "    </style>\n",
              "\n",
              "    <div class=\"app-header-responsive\">\n",
              "        <a href=\"https://youtube.com/@crown08?si=3Jhi8pxZt82YQEtw\" target=\"_blank\" class=\"header-brand-wrap interactable-node\">\n",
              "            <img src=\"https://unavatar.io/youtube/crown08\" alt=\"Crown\" onerror=\"this.onerror=null; this.src='https://i.ytimg.com/vi/Fl3l0GPyy-Y/hqdefault.jpg';\">\n",
              "            <h1 class=\"app-title-main\">Crown<span style=\"color: var(--primary-yellow);\">Scaler</span></h1>\n",
              "        </a>\n",
              "\n",
              "        <div class=\"header-right-capsule\">\n",
              "            <div class=\"header-social-capsule\">\n",
              "                <style>.social-symbol.tg i { color: #2AABEE; font-size: 11px; } @media (max-width: 480px) { .social-symbol.tg i { font-size: 9px !important; } }</style>\n",
              "                <a href=\"https://youtube.com/@crown08?si=3Jhi8pxZt82YQEtw\" target=\"_blank\" class=\"social-symbol yt interactable-node\" title=\"YouTube\"><i class=\"fa-brands fa-youtube\"></i></a>\n",
              "                <a href=\"https://discord.gg/dnuB3N9W9J\" target=\"_blank\" class=\"social-symbol dc interactable-node\" title=\"Discord\"><i class=\"fa-brands fa-discord\"></i></a>\n",
              "                <a href=\"https://t.me/CrownsVoid\" target=\"_blank\" class=\"social-symbol tg interactable-node\" title=\"Telegram\"><i class=\"fa-brands fa-telegram\"></i></a>\n",
              "                <a href=\"https://crown-project.pages.dev/\" target=\"_blank\" class=\"social-symbol wb interactable-node\" title=\"Website\"><i class=\"fa-solid fa-globe\"></i></a>\n",
              "            </div>\n",
              "\n",
              "            <!-- Theme Toggle Button -->\n",
              "            <div class=\"circle-icon-btn interactable-node\" onclick=\"cycleTheme()\" title=\"Toggle Theme\" style=\"width: 28px; height: 28px;\">\n",
              "                <span class=\"material-icons-round\" id=\"themeToggleBtn\" style=\"font-size: 16px;\">light_mode</span>\n",
              "            </div>\n",
              "        </div>\n",
              "\n",
              "        <!-- Silent Sound State Keeper (Maintains chime compatibility without UI dropdown) -->\n",
              "        <input type=\"checkbox\" id=\"soundToggle\" checked style=\"display: none;\">\n",
              "    </div>\n",
              "\n",
              "    <div id=\"view-upscale\" class=\"view-section active-view\">\n",
              "        <div class=\"compose-card span-full\">\n",
              "            <div id=\"dropZone\" class=\"upload-box interactable-node\" onclick=\"document.getElementById('nativeFileInput').click()\">\n",
              "                <div class=\"upload-circle\"><span class=\"material-icons-round icon\">cloud_upload</span></div>\n",
              "                <div class=\"upload-title\">Select Videos or Images</div>\n",
              "                <div class=\"upload-subtitle\" style=\"white-space: nowrap;\">Tap or drag files here to upload</div>\n",
              "                <input type=\"file\" accept=\"video/*, image/*\" multiple id=\"nativeFileInput\" style=\"display: none;\" onclick=\"this.value=null;\" onchange=\"handleMultipleFiles(this)\">\n",
              "            </div>\n",
              "\n",
              "            <!-- Compact Direct Link & Magnet Bar (Exact 26px Height Match) -->\n",
              "            <div style=\"display: flex; gap: 5px; align-items: center; margin-top: 4px; width: 100%; box-sizing: border-box;\">\n",
              "                <div style=\"position: relative; flex: 1; min-width: 0;\">\n",
              "                    <input type=\"text\" id=\"remoteUrlInput\" placeholder=\"Paste Direct Link, Drive, or Magnet URL...\" style=\"width: 100%; background: var(--surface-inner); border: 1px solid var(--border-distinct); border-radius: 100px; padding: 4px 10px 4px 26px; color: var(--text-primary); font-family: var(--font); font-size: 10.5px; outline: none; box-sizing: border-box; height: 26px; line-height: 26px;\">\n",
              "                    <span class=\"material-icons-round\" style=\"position: absolute; left: 8px; top: 50%; transform: translateY(-50%); font-size: 14px; color: var(--primary-yellow); pointer-events: none;\">link</span>\n",
              "                </div>\n",
              "                <button class=\"circle-icon-btn interactable-node\" id=\"btnFetchUrl\" onclick=\"triggerRemoteDownload()\" title=\"Download from URL / Magnet\" style=\"width: 26px !important; height: 26px !important; min-width: 26px !important; min-height: 26px !important; border-radius: 50% !important; background: linear-gradient(135deg, var(--primary-yellow), var(--dark-yellow)); color: #000000; display: flex; align-items: center; justify-content: center; flex-shrink: 0; border: none; cursor: pointer; box-shadow: 0 2px 6px var(--card-glow); padding: 0;\">\n",
              "                    <span class=\"material-icons-round icon\" id=\"fetchUrlIcon\" style=\"font-size: 14px !important; color: #000000; line-height: 1;\">arrow_downward</span>\n",
              "                </button>\n",
              "            </div>\n",
              "\n",
              "            <script>\n",
              "                async function triggerRemoteDownload() {\n",
              "                    const input = document.getElementById('remoteUrlInput');\n",
              "                    const btn = document.getElementById('btnFetchUrl');\n",
              "                    const icon = document.getElementById('fetchUrlIcon');\n",
              "                    if (!input || !btn) return;\n",
              "\n",
              "                    const url = input.value.trim();\n",
              "                    if (!url) {\n",
              "                        showToast(\"Please enter a valid Direct Link, Drive, or Magnet URL.\");\n",
              "                        return;\n",
              "                    }\n",
              "\n",
              "                    btn.style.pointerEvents = 'none';\n",
              "                    btn.style.opacity = '0.7';\n",
              "                    if (icon) { icon.innerText = 'sync'; icon.classList.add('fa-spin'); }\n",
              "                    showToast(\"Fetching media into queue, please wait...\");\n",
              "\n",
              "                    try {\n",
              "                        const res = await google.colab.kernel.invokeFunction('notebook.command', [JSON.stringify({command: \"FETCH_URL\", url: url})], {});\n",
              "                        const result = res.data['application/json'];\n",
              "                        if (result && result.success) {\n",
              "                            showToast(\"Downloaded & added to queue successfully!\");\n",
              "                            input.value = \"\";\n",
              "                            triggerPythonRefresh();\n",
              "                        } else {\n",
              "                            showToast(\"Download failed: \" + (result?.error || \"Unknown error\"));\n",
              "                        }\n",
              "                    } catch (err) {\n",
              "                        showToast(\"Error downloading file: \" + err.message);\n",
              "                    } finally {\n",
              "                        btn.style.pointerEvents = 'auto';\n",
              "                        btn.style.opacity = '1';\n",
              "                        if (icon) { icon.classList.remove('fa-spin'); icon.innerText = 'download'; }\n",
              "                    }\n",
              "                }\n",
              "            </script>\n",
              "\n",
              "            <div style=\"display: flex; justify-content: space-between; align-items: center; margin-top: 16px;\">\n",
              "                <h3 class=\"component-title\" style=\"color: var(--text-muted);\">Videos Uploaded</h3>\n",
              "                <span class=\"material-icons-round icon-btn interactable-node\" style=\"color:var(--text-muted); font-size: 20px;\" onclick=\"triggerPythonRefresh()\" title=\"Refresh Files\">refresh</span>\n",
              "            </div>\n",
              "            <div id=\"unsupportedCard\" class=\"compose-card\" style=\"display:none; background: var(--surface-inner); border: 1px solid var(--highlight-cta); border-radius: 20px; padding: 14px; margin-top: 12px;\">\n",
              "                <h4 style=\"margin:0; color: var(--highlight-cta); font-size: 14px; font-weight: 700;\">\n",
              "                    <span class=\"material-icons-round icon\" style=\"font-size: 18px; vertical-align: middle;\">warning</span>\n",
              "                    <span id=\"unsupportedCount\">0</span> file(s) failed during processing\n",
              "                </h4>\n",
              "                <ul id=\"unsupportedFileList\" style=\"list-style: none; padding: 0; margin: 8px 0 0 0; font-size: 12px; color: var(--text-muted);\"></ul>\n",
              "            </div>\n",
              "            <div class=\"file-stack\" id=\"fileStack\">\n",
              "                <div id=\"fileStackLoader\" style=\"display:flex; align-items:center; justify-content:center; gap:8px; padding:20px 0; color:var(--text-muted); font-size:11.5px; font-weight:700;\">\n",
              "                    <svg class=\"md3-spinner\" style=\"width:16px;height:16px;margin:0;\" viewBox=\"0 0 50 50\"><circle cx=\"25\" cy=\"25\" r=\"20\"></circle></svg>\n",
              "                    <span>Loading queue...</span>\n",
              "                </div>\n",
              "            </div>\n",
              "        </div>\n",
              "\n",
              "        <button class=\"action-button-main interactable-node\" id=\"startUpscaleBtn\" onclick=\"triggerUpscaleStateToggle()\">\n",
              "            <span class=\"material-icons-round icon\">auto_awesome</span> Start Upscale\n",
              "        </button>\n",
              "\n",
              "        <div class=\"dashboard-layout\">\n",
              "            <div class=\"compose-card span-full\">\n",
              "                <div style=\"display: flex; justify-content: space-between; align-items: center; width: 100%;\">\n",
              "                    <div class=\"component-label-group\"><span class=\"material-icons-round icon\">psychology</span><h3 class=\"component-title\">AI Engine Model</h3></div>\n",
              "                    <button class=\"selectable-chip interactable-node\" id=\"m4\" onclick=\"selectModel('m4', 'Custom')\" style=\"height: 22px !important; padding: 0 9px !important; font-size: 9.5px !important; border: 1px dashed rgba(255, 214, 0, 0.55) !important; display: inline-flex; align-items: center; gap: 4px;\">\n",
              "                        <span class=\"material-icons-round\" style=\"font-size: 12px; color: currentColor;\">add_circle_outline</span>\n",
              "                        <span>Custom Model</span>\n",
              "                    </button>\n",
              "                </div>\n",
              "                <style>\n",
              "                    .chip-container {\n",
              "                        display: flex !important;\n",
              "                        align-items: center !important;\n",
              "                        gap: 6px !important;\n",
              "                        padding: 3px 30px 3px 1px !important;\n",
              "                        -webkit-mask-image: linear-gradient(to right, black calc(100% - 48px), transparent 100%);\n",
              "                        mask-image: linear-gradient(to right, black calc(100% - 48px), transparent 100%);\n",
              "                    }\n",
              "                    .selectable-chip {\n",
              "                        display: inline-flex !important;\n",
              "                        align-items: center !important;\n",
              "                        gap: 4.5px !important;\n",
              "                        height: 23px !important;\n",
              "                        padding: 0 8px !important;\n",
              "                        font-size: 10px !important;\n",
              "                        font-weight: 700 !important;\n",
              "                        border-radius: 100px !important;\n",
              "                        white-space: nowrap !important;\n",
              "                        flex-shrink: 0 !important;\n",
              "                        box-sizing: border-box !important;\n",
              "                    }\n",
              "                    .model-cat-badge {\n",
              "                        font-size: 7px;\n",
              "                        font-weight: 800;\n",
              "                        padding: 0 4.5px;\n",
              "                        height: 13px;\n",
              "                        display: inline-flex;\n",
              "                        align-items: center;\n",
              "                        justify-content: center;\n",
              "                        border-radius: 100px;\n",
              "                        border: 1px solid currentColor;\n",
              "                        opacity: 0.85;\n",
              "                        letter-spacing: 0.2px;\n",
              "                        line-height: 1;\n",
              "                    }\n",
              "                    .model-sub-badge {\n",
              "                        font-size: 6.5px;\n",
              "                        font-weight: 800;\n",
              "                        padding: 0 4.5px;\n",
              "                        height: 13px;\n",
              "                        display: inline-flex;\n",
              "                        align-items: center;\n",
              "                        justify-content: center;\n",
              "                        border-radius: 100px;\n",
              "                        background: rgba(255, 214, 0, 0.12);\n",
              "                        color: var(--primary-yellow);\n",
              "                        border: 1px solid rgba(255, 214, 0, 0.32);\n",
              "                        letter-spacing: 0.3px;\n",
              "                        line-height: 1;\n",
              "                        margin-left: 2px;\n",
              "                    }\n",
              "                    .selectable-chip.active .model-sub-badge {\n",
              "                        background: rgba(0, 0, 0, 0.14);\n",
              "                        border-color: rgba(0, 0, 0, 0.25);\n",
              "                        color: #000000;\n",
              "                    }\n",
              "                </style>\n",
              "                <div class=\"chip-container\" onscroll=\"const s=this.scrollLeft>5; this.style.webkitMaskImage=s?'linear-gradient(to right, transparent, black 18px, black calc(100% - 48px), transparent)':'linear-gradient(to right, black calc(100% - 48px), transparent)'; this.style.maskImage=this.style.webkitMaskImage;\">\n",
              "                    <button class=\"selectable-chip interactable-node active\" id=\"m2\" onclick=\"selectModel('m2', 'Anime-Pro')\"><span class=\"model-cat-badge\">ANIME</span>Anime-Pro</button>\n",
              "                    <button class=\"selectable-chip interactable-node\" id=\"m7\" onclick=\"selectModel('m7', 'ANIME V5 XYETHER')\" title=\"ANIME V5 XYETHER\"><span class=\"model-cat-badge\">ANIME</span>Anime-V5<span class=\"model-sub-badge\">XYETHER</span></button>\n",
              "                    <button class=\"selectable-chip interactable-node\" id=\"m5\" onclick=\"selectModel('m5', 'IRLV2-MOTSR-XYETHER')\" title=\"MotSR XYETHER\"><span class=\"model-cat-badge\">IRL</span>MotSR<span class=\"model-sub-badge\">XYETHER</span></button>\n",
              "                    <button class=\"selectable-chip interactable-node\" id=\"m8\" onclick=\"selectModel('m8', 'STRONG V4 XYETHER')\" title=\"STRONG V4 XYETHER\"><span class=\"model-cat-badge\">ANIME</span>Strong-V4<span class=\"model-sub-badge\">XYETHER</span></button>\n",
              "                    <button class=\"selectable-chip interactable-node\" id=\"m9\" onclick=\"selectModel('m9', 'QUALITY SSJ XYETHER')\" title=\"QUALITY SSJ XYETHER\"><span class=\"model-cat-badge\">ANIME</span>Quality-SSJ<span class=\"model-sub-badge\">XYETHER</span></button>\n",
              "                    <button class=\"selectable-chip interactable-node\" id=\"m6\" onclick=\"selectModel('m6', 'STRONG-V3 XYETHER')\" title=\"STRONG-V3 XYETHER\"><span class=\"model-cat-badge\">ANIME</span>Strong-V3<span class=\"model-sub-badge\">XYETHER</span></button>\n",
              "                    <button class=\"selectable-chip interactable-node\" id=\"m1\" onclick=\"selectModel('m1', 'Anime Ultra')\"><span class=\"model-cat-badge\">ANIME</span>Anime Ultra</button>\n",
              "                    <button class=\"selectable-chip interactable-node\" id=\"m3\" onclick=\"selectModel('m3', 'Real World')\"><span class=\"model-cat-badge\">IRL</span>Real World</button>\n",
              "                </div>\n",
              "\n",
              "<div class=\"custom-model-drawer\" id=\"customModelDrawer\" style=\"padding: 12px; gap: 10px; border-radius: 18px; background: linear-gradient(180deg, var(--surface-inner) 0%, var(--surface-card) 100%); border: 1px solid rgba(255, 214, 0, 0.32); box-sizing: border-box; width: 100%; box-shadow: 0 8px 24px rgba(0,0,0,0.22);\">\n",
              "                    <!-- Studio Vault Header -->\n",
              "                    <div style=\"display:flex; justify-content:space-between; align-items:center;\">\n",
              "                        <div style=\"display:flex; align-items:center; gap:7px;\">\n",
              "                            <div style=\"width:24px; height:24px; border-radius:7px; background:var(--card-glow); border:1px solid rgba(255,214,0,0.35); display:flex; align-items:center; justify-content:center; flex-shrink:0;\">\n",
              "                                <span class=\"material-icons-round\" style=\"font-size:14px; color:var(--primary-yellow);\">psychology</span>\n",
              "                            </div>\n",
              "                            <div style=\"display:flex; flex-direction:column;\">\n",
              "                                <span style=\"font-size:11.5px; font-weight:800; color:var(--text-primary); letter-spacing:-0.2px; line-height:1.1;\">Custom Neural Vault</span>\n",
              "                                <span style=\"font-size:8.5px; font-weight:600; color:var(--text-muted);\">Auto-converts PyTorch & Safetensors</span>\n",
              "                            </div>\n",
              "                        </div>\n",
              "                        <div style=\"display:flex; align-items:center; gap:3.5px;\">\n",
              "                            <span class=\"tech-pill\" style=\"font-size:7px !important; padding:1.5px 5px !important;\">.PTH</span>\n",
              "                            <span class=\"tech-pill\" style=\"font-size:7px !important; padding:1.5px 5px !important;\">.ONNX</span>\n",
              "                            <span class=\"tech-pill\" style=\"font-size:7px !important; padding:1.5px 5px !important;\">.TRT</span>\n",
              "                        </div>\n",
              "                    </div>\n",
              "\n",
              "                    <!-- ACTIVE HARDWARE STATUS CARD (Visible when model is loaded) -->\n",
              "                    <div id=\"customModelActiveCard\" style=\"display:none; background:var(--surface-card); border:1px solid var(--primary-yellow); border-radius:14px; padding:8px 10px; gap:9px; align-items:center; box-sizing:border-box; box-shadow: 0 4px 14px var(--card-glow);\">\n",
              "                        <div style=\"width:30px; height:30px; border-radius:9px; background:var(--card-glow); border:1px solid rgba(255,214,0,0.45); display:flex; align-items:center; justify-content:center; color:var(--primary-yellow); flex-shrink:0;\">\n",
              "                            <span class=\"material-icons-round\" style=\"font-size:17px;\">memory</span>\n",
              "                        </div>\n",
              "                        <div style=\"display:flex; flex-direction:column; gap:2px; flex:1; min-width:0;\">\n",
              "                            <span id=\"activeModelCardName\" style=\"font-size:11px; font-weight:800; color:var(--text-primary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;\">model.onnx</span>\n",
              "                            <div style=\"display:flex; align-items:center; gap:5px; font-size:8.5px; font-weight:700;\">\n",
              "                                <span id=\"activeModelCardType\" class=\"tech-pill\" style=\"font-size:7px !important; padding:1px 5px !important;\">ONNX</span>\n",
              "                                <span id=\"activeModelCardSize\" style=\"color:var(--text-muted); font-size:8.5px;\">65 MB</span>\n",
              "                                <span style=\"color:#10B981; display:inline-flex; align-items:center; gap:2.5px; margin-left:auto; font-size:8.5px; font-weight:800; background:rgba(16,185,129,0.12); padding:1.5px 6px; border-radius:100px; border:1px solid rgba(16,185,129,0.3);\"><span class=\"material-icons-round\" style=\"font-size:10px;\">check_circle</span> Ready</span>\n",
              "                            </div>\n",
              "                        </div>\n",
              "                        <div class=\"circle-icon-btn interactable-node\" onclick=\"removeCustomModel()\" style=\"width:22px !important; height:22px !important;\" title=\"Remove Model\">\n",
              "                            <span class=\"material-icons-round icon\" style=\"font-size:12px !important;\">close</span>\n",
              "                        </div>\n",
              "                    </div>\n",
              "\n",
              "                    <!-- UPLOAD & LINK ACTION HUB -->\n",
              "                    <div id=\"customModelInputsWrap\" style=\"display:flex; flex-direction:column; gap:7px;\">\n",
              "                        <!-- Sleek Mini Upload Drop/Tap Card -->\n",
              "                        <label for=\"nativeModelInput\" class=\"interactable-node\" style=\"display:flex; align-items:center; justify-content:space-between; gap:8px; background:var(--surface-card); border:1.5px dashed rgba(255,214,0,0.45); padding:8px 11px; border-radius:14px; cursor:pointer; margin:0; transition:all 0.2s ease;\">\n",
              "                            <div style=\"display:flex; align-items:center; gap:8px; min-width:0;\">\n",
              "                                <div style=\"width:26px; height:26px; border-radius:50%; background:var(--card-glow); display:flex; align-items:center; justify-content:center; flex-shrink:0;\">\n",
              "                                    <span class=\"material-icons-round\" style=\"font-size:15px; color:var(--primary-yellow);\">upload_file</span>\n",
              "                                </div>\n",
              "                                <div style=\"display:flex; flex-direction:column; min-width:0;\">\n",
              "                                    <span id=\"customModelUploadLabel\" style=\"font-size:10.5px; font-weight:800; color:var(--text-primary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;\">Upload Model from Device</span>\n",
              "                                    <span style=\"font-size:8.5px; color:var(--text-muted); font-weight:600;\">Tap to browse .pth, .safetensors, .onnx, .engine</span>\n",
              "                                </div>\n",
              "                            </div>\n",
              "                            <span style=\"background:var(--surface-inner); border:1px solid var(--border-distinct); color:var(--primary-yellow); font-size:8.5px; font-weight:800; padding:3px 8px; border-radius:100px; flex-shrink:0;\">Browse</span>\n",
              "                        </label>\n",
              "                        <input type=\"file\" id=\"nativeModelInput\" accept=\".engine,.trt,.onnx,.pth,.pt,.safetensors,.ckpt,.bin\" style=\"display:none;\" onclick=\"this.value=null;\" onchange=\"handleStrictModelUpload(this)\">\n",
              "\n",
              "                        <!-- Clean Side-by-Side URL Bar -->\n",
              "                        <div style=\"display:flex; gap:5px; align-items:center; width:100%; box-sizing:border-box;\">\n",
              "                            <div style=\"position:relative; flex:1; min-width:0;\">\n",
              "                                <span class=\"material-icons-round\" style=\"position:absolute; left:9px; top:50%; transform:translateY(-50%); font-size:13px; color:var(--primary-yellow); pointer-events:none;\">link</span>\n",
              "                                <input type=\"text\" class=\"model-input-link\" id=\"customModelUrl\" placeholder=\"Paste HuggingFace, Drive, or Direct Model URL...\" oninput=\"STATE_CUSTOM_URL=this.value.trim()\" style=\"width:100%; height:26px !important; font-size:10px; font-family:var(--font); padding:4px 10px 4px 26px; border-radius:100px; background:var(--surface-card); border:1px solid var(--border-distinct); outline:none; box-sizing:border-box; color:var(--text-primary);\">\n",
              "                            </div>\n",
              "                            <button class=\"circle-icon-btn interactable-node\" id=\"btnFetchModel\" onclick=\"triggerFetchModelUrl()\" title=\"Download Model from URL\" style=\"width:26px !important; height:26px !important; min-width:26px !important; min-height:26px !important; border-radius:50% !important; background:linear-gradient(135deg, var(--primary-yellow), var(--dark-yellow)); color:#000; display:flex; align-items:center; justify-content:center; border:none; cursor:pointer; box-shadow:0 2px 6px var(--card-glow); padding:0; flex-shrink:0;\">\n",
              "                                <span class=\"material-icons-round icon\" id=\"fetchModelIcon\" style=\"font-size:14px !important; color:#000; line-height:1;\">arrow_downward</span>\n",
              "                            </button>\n",
              "                        </div>\n",
              "                    </div>\n",
              "\n",
              "                    <!-- SEGMENTED EXECUTION CONTROL -->\n",
              "                    <div id=\"onnxModeSection\" style=\"display:flex; flex-direction:column; gap:6px; border-top:1px dashed var(--border-distinct); padding-top:8px; width:100%; box-sizing:border-box;\">\n",
              "                        <div style=\"display:flex; justify-content:space-between; align-items:center; padding:0 2px;\">\n",
              "                            <div style=\"display:flex; align-items:center; gap:5px;\">\n",
              "                                <span class=\"material-icons-round\" style=\"font-size:14px; color:var(--primary-yellow);\">bolt</span>\n",
              "                                <span style=\"font-size:10.5px; font-weight:800; color:var(--text-primary); letter-spacing:-0.1px;\">Runtime Engine</span>\n",
              "                            </div>\n",
              "                            <div class=\"interactable-node\" onclick=\"openOnnxInfoModal()\" style=\"display:inline-flex; align-items:center; gap:3px; font-size:9px; font-weight:700; color:var(--text-muted); cursor:pointer; background:var(--surface-card); padding:2px 7px; border-radius:100px; border:1px solid var(--border-distinct);\" title=\"Execution mode info\">\n",
              "                                <span class=\"material-icons-round\" style=\"font-size:11px; color:var(--primary-yellow);\">info</span>\n",
              "                                <span>Info</span>\n",
              "                            </div>\n",
              "                        </div>\n",
              "                        <div style=\"display:grid; grid-template-columns:1fr 1fr; gap:6px; width:100%; box-sizing:border-box;\">\n",
              "                            <button type=\"button\" class=\"block-selector interactable-node active\" id=\"btnOnnxNormal\" onclick=\"selectOnnxMode('normal', true)\" style=\"display:inline-flex !important; align-items:center !important; justify-content:center !important; gap:4px !important; height:26px !important; padding:0 8px !important; font-size:10px !important; border-radius:100px !important;\">\n",
              "                                <span class=\"material-icons-round\" style=\"font-size:13px; color:currentColor;\">play_arrow</span>\n",
              "                                <span>Standard (ONNX)</span>\n",
              "                            </button>\n",
              "                            <button type=\"button\" class=\"block-selector interactable-node\" id=\"btnOnnxConvert\" onclick=\"selectOnnxMode('convert', true)\" style=\"display:inline-flex !important; align-items:center !important; justify-content:center !important; gap:4px !important; height:26px !important; padding:0 8px !important; font-size:10px !important; border-radius:100px !important;\">\n",
              "                                <span class=\"material-icons-round\" style=\"font-size:13px; color:currentColor;\">bolt</span>\n",
              "                                <span>TRT Engine (Fast)</span>\n",
              "                            </button>\n",
              "                        </div>\n",
              "                    </div>\n",
              "                </div>\n",
              "\n",
              "                <!-- ONNX MODE EXPLANATION MODAL (Compact 250px Layout) -->\n",
              "                <div class=\"modal-backdrop\" id=\"onnxInfoModal\">\n",
              "                    <div class=\"modal-card\" style=\"width: 84%; max-width: 250px; padding: 12px 14px; gap: 8px; border-radius: 18px; box-sizing: border-box; text-align: left;\">\n",
              "                        <div style=\"display:flex; align-items:center; gap:6px; justify-content:center;\">\n",
              "                            <span class=\"material-icons-round\" style=\"color:var(--primary-yellow); font-size:18px;\">psychology</span>\n",
              "                            <h4 class=\"modal-title\" style=\"font-size:12.5px; font-weight:800; margin:0;\">Execution Modes</h4>\n",
              "                        </div>\n",
              "\n",
              "                        <div style=\"display:flex; flex-direction:column; gap:5px; font-size:9.5px; color:var(--text-secondary); line-height:1.35; background:var(--surface-inner); border:1px solid var(--border-distinct); border-radius:10px; padding:7px 9px; box-sizing: border-box;\">\n",
              "                            <div>\n",
              "                                <strong style=\"color:var(--primary-yellow); display:flex; align-items:center; gap:3px; margin-bottom:1px; font-size:10px;\">\n",
              "                                    <span class=\"material-icons-round\" style=\"font-size:12px;\">play_arrow</span> 1. Standard (GPU):\n",
              "                                </strong>\n",
              "                                Runs directly via ONNX Runtime. Zero wait time, starts rendering instantly.\n",
              "                            </div>\n",
              "\n",
              "                            <div style=\"border-top:1px dashed var(--border-distinct); padding-top:4px;\">\n",
              "                                <strong style=\"color:var(--primary-yellow); display:flex; align-items:center; gap:3px; margin-bottom:1px; font-size:10px;\">\n",
              "                                    <span class=\"material-icons-round\" style=\"font-size:12px;\">bolt</span> 2. TRT Engine:\n",
              "                                </strong>\n",
              "                                Compiles to TensorRT FP16 (1-2 mins first time). Provides maximum rendering speed.\n",
              "                            </div>\n",
              "                        </div>\n",
              "\n",
              "                        <div class=\"modal-actions\" style=\"margin-top:1px;\">\n",
              "                            <button class=\"modal-btn save interactable-node\" style=\"padding: 6px 12px; font-size: 10.5px; border-radius: 100px; width: 100%;\" onclick=\"dismissModalCenter('onnxInfoModal')\">Got It</button>\n",
              "                        </div>\n",
              "                    </div>\n",
              "                </div>\n",
              "\n",
              "                <script>\n",
              "                    let STATE_ONNX_MODE = \"normal\";\n",
              "\n",
              "                    function renderCustomModelCard(meta) {\n",
              "                        const card = document.getElementById('customModelActiveCard');\n",
              "                        const inputs = document.getElementById('customModelInputsWrap');\n",
              "                        const onnxSec = document.getElementById('onnxModeSection');\n",
              "                        if (!card || !inputs) return;\n",
              "\n",
              "                        if (meta && meta.name) {\n",
              "                            document.getElementById('activeModelCardName').innerText = meta.name;\n",
              "                            document.getElementById('activeModelCardType').innerText = (meta.type || 'MODEL').toUpperCase();\n",
              "                            document.getElementById('activeModelCardSize').innerText = meta.size || '';\n",
              "                            card.style.display = 'flex';\n",
              "                            inputs.style.display = 'none';\n",
              "\n",
              "                            // Agar file direct .engine hai toh ONNX Mode options hide ho jayenge\n",
              "                            if (meta.type && meta.type.toLowerCase() === 'engine') {\n",
              "                                if (onnxSec) onnxSec.style.display = 'none';\n",
              "                            } else {\n",
              "                                if (onnxSec) onnxSec.style.display = 'flex';\n",
              "                            }\n",
              "                            localStorage.setItem('cs_custom_model_meta', JSON.stringify(meta));\n",
              "                        } else {\n",
              "                            card.style.display = 'none';\n",
              "                            inputs.style.display = 'flex';\n",
              "                            if (onnxSec) onnxSec.style.display = 'flex';\n",
              "                            localStorage.removeItem('cs_custom_model_meta');\n",
              "                        }\n",
              "                        if (typeof updateFourXAvailability === 'function') {\n",
              "                            updateFourXAvailability();\n",
              "                        }\n",
              "                    }\n",
              "\n",
              "                    function removeCustomModel() {\n",
              "                        renderCustomModelCard(null);\n",
              "                        STATE_CUSTOM_URL = \"\";\n",
              "                        const urlInput = document.getElementById('customModelUrl');\n",
              "                        if (urlInput) urlInput.value = \"\";\n",
              "                        const label = document.getElementById('customModelUploadLabel');\n",
              "                        if (label) label.innerText = \"Upload File (.onnx / .engine)\";\n",
              "                        google.colab.kernel.invokeFunction('notebook.command', [JSON.stringify({command: \"REMOVE_CUSTOM_MODEL\"})], {}).catch(()=>{});\n",
              "                        showToast(\"Custom model removed.\");\n",
              "                    }\n",
              "\n",
              "                    // RELIABLE MODEL UPLOADER WITH INSTANT ONNX CONVERSION\n",
              "                    async function handleStrictModelUpload(input) {\n",
              "                        if (!input.files || input.files.length === 0) return;\n",
              "                        const file = input.files[0];\n",
              "                        const dotIdx = file.name.lastIndexOf('.');\n",
              "                        const ext = dotIdx !== -1 ? file.name.substring(dotIdx).toLowerCase() : \"\";\n",
              "\n",
              "                        const allowedModelExts = ['.onnx', '.engine', '.trt', '.pth', '.pt', '.safetensors', '.ckpt', '.bin'];\n",
              "                        if (!allowedModelExts.includes(ext)) {\n",
              "                            showToast(\"Invalid format. Use .pth, .safetensors, .onnx, or .engine\");\n",
              "                            input.value = \"\";\n",
              "                            return;\n",
              "                        }\n",
              "\n",
              "                        const label = document.getElementById('customModelUploadLabel');\n",
              "                        if (label) label.innerText = `Uploading ${file.name}...`;\n",
              "                        showToast(`Uploading: ${file.name}`);\n",
              "\n",
              "                        const chunkSize = 1024 * 1024;\n",
              "                        let offset = 0;\n",
              "                        let modelRetryCount = 0;\n",
              "                        const maxModelRetries = 8;\n",
              "\n",
              "                        function invokeModelChunkWithTimeout(args, timeoutMs = 45000) {\n",
              "                            return new Promise((resolve, reject) => {\n",
              "                                const timer = setTimeout(() => reject(new Error(\"Model Upload RPC Timeout\")), timeoutMs);\n",
              "                                google.colab.kernel.invokeFunction('notebook.upload_model_chunk', args, {})\n",
              "                                    .then(res => { clearTimeout(timer); resolve(res); })\n",
              "                                    .catch(err => { clearTimeout(timer); reject(err); });\n",
              "                            });\n",
              "                        }\n",
              "\n",
              "                        function pushChunk() {\n",
              "                            const chunkSlice = file.slice(offset, offset + chunkSize);\n",
              "                            const reader = new FileReader();\n",
              "                            reader.onerror = () => setTimeout(pushChunk, 1000);\n",
              "                            reader.onload = function(e) {\n",
              "                                const resultStr = e.target.result || \"\";\n",
              "                                const commaIdx = resultStr.indexOf(',');\n",
              "                                const b64 = commaIdx !== -1 ? resultStr.substring(commaIdx + 1) : \"\";\n",
              "                                const isLast = (offset + chunkSlice.size >= file.size);\n",
              "\n",
              "                                if (isLast && ext !== '.onnx' && ext !== '.engine' && ext !== '.trt') {\n",
              "                                    if (label) label.innerText = \"Converting to ONNX (~2s)...\";\n",
              "                                }\n",
              "\n",
              "                                invokeModelChunkWithTimeout([file.name, b64, (offset === 0), isLast, offset], isLast ? 90000 : 30000)\n",
              "                                    .then((res) => {\n",
              "                                        const resData = res && res.data ? res.data['application/json'] : null;\n",
              "                                        if (resData && resData.reset) {\n",
              "                                            offset = 0;\n",
              "                                            modelRetryCount = 0;\n",
              "                                            return pushChunk();\n",
              "                                        }\n",
              "                                        if (!resData || resData.success === false) {\n",
              "                                            throw new Error((resData && resData.error) ? resData.error : \"Model upload/conversion failed on server\");\n",
              "                                        }\n",
              "\n",
              "                                        modelRetryCount = 0;\n",
              "                                        offset += chunkSlice.size;\n",
              "                                        const pct = Math.min(100, Math.round((offset / file.size) * 100));\n",
              "                                        if (label && offset < file.size) label.innerText = `Uploading ${pct}%`;\n",
              "\n",
              "                                        if (offset < file.size) {\n",
              "                                            pushChunk();\n",
              "                                        } else {\n",
              "                                            STATE_CUSTOM_URL = \"\";\n",
              "                                            const urlInput = document.getElementById('customModelUrl');\n",
              "                                            if (urlInput) urlInput.value = \"\";\n",
              "\n",
              "                                            const finalType = resData.type || (ext === '.engine' || ext === '.trt' ? 'ENGINE' : 'ONNX');\n",
              "                                            const szMb = resData.size_mb ? resData.size_mb + \" MB\" : (file.size / (1024 * 1024)).toFixed(1) + \" MB\";\n",
              "                                            const displayName = (finalType === 'ONNX' && ext !== '.onnx') ? file.name.substring(0, dotIdx) + \".onnx\" : file.name;\n",
              "\n",
              "                                            const modelMeta = {\n",
              "                                                name: displayName,\n",
              "                                                type: finalType,\n",
              "                                                size: szMb\n",
              "                                            };\n",
              "                                            renderCustomModelCard(modelMeta);\n",
              "\n",
              "                                            if (resData.converted) {\n",
              "                                                showToast(`Converted & Ready: ${displayName}`);\n",
              "                                            } else {\n",
              "                                                showToast(`Model ready: ${file.name}`);\n",
              "                                            }\n",
              "                                            if (label) label.innerText = \"Upload Model (.pth, .safetensors, .onnx, .engine)\";\n",
              "                                            input.value = \"\";\n",
              "                                        }\n",
              "                                    })\n",
              "                                    .catch((err) => {\n",
              "                                        modelRetryCount++;\n",
              "                                        if (modelRetryCount <= maxModelRetries && offset < file.size) {\n",
              "                                            if (label) label.innerText = `Reconnecting (${modelRetryCount}/${maxModelRetries})...`;\n",
              "                                            setTimeout(pushChunk, 1500);\n",
              "                                        } else {\n",
              "                                            if (label) label.innerText = \"Upload Model (.pth, .safetensors, .onnx, .engine)\";\n",
              "                                            showToast(\"Error: \" + err.message);\n",
              "                                            input.value = \"\";\n",
              "                                        }\n",
              "                                    });\n",
              "                            };\n",
              "                            reader.readAsDataURL(chunkSlice);\n",
              "                        }\n",
              "                        pushChunk();\n",
              "                    }\n",
              "\n",
              "                    // STRICT LINK DOWNLOAD (Google Drive / Direct URL)\n",
              "                    async function triggerFetchModelUrl() {\n",
              "                        const input = document.getElementById('customModelUrl');\n",
              "                        const btn = document.getElementById('btnFetchModel');\n",
              "                        const icon = document.getElementById('fetchModelIcon');\n",
              "                        if (!input || !btn) return;\n",
              "\n",
              "                        const url = input.value.trim();\n",
              "                        if (!url) {\n",
              "                            showToast(\"Please enter a valid Google Drive or Model link.\");\n",
              "                            return;\n",
              "                        }\n",
              "\n",
              "                        btn.style.pointerEvents = 'none';\n",
              "                        btn.style.opacity = '0.7';\n",
              "                        if (icon) { icon.innerText = 'sync'; icon.classList.add('fa-spin'); }\n",
              "                        showToast(\"Downloading & converting model, please wait...\");\n",
              "\n",
              "                        try {\n",
              "                            const res = await google.colab.kernel.invokeFunction('notebook.command', [JSON.stringify({command: \"FETCH_MODEL_URL\", url: url})], {});\n",
              "                            const result = res && res.data ? res.data['application/json'] : null;\n",
              "                            if (result && result.success) {\n",
              "                                STATE_CUSTOM_URL = url;\n",
              "                                const rawFilename = url.split('/').pop().split('?')[0] || `custom_model.${result.type.toLowerCase()}`;\n",
              "                                const dot = rawFilename.lastIndexOf('.');\n",
              "                                const base = dot !== -1 ? rawFilename.substring(0, dot) : rawFilename;\n",
              "                                const displayName = (result.type === 'ONNX' && !rawFilename.toLowerCase().endsWith('.onnx'))\n",
              "                                    ? base + '.onnx'\n",
              "                                    : rawFilename;\n",
              "\n",
              "                                const modelMeta = {\n",
              "                                    name: displayName,\n",
              "                                    type: result.type,\n",
              "                                    size: result.size_mb + \" MB\"\n",
              "                                };\n",
              "                                renderCustomModelCard(modelMeta);\n",
              "                                showToast(`Model loaded successfully! (${result.type} - ${result.size_mb} MB)`);\n",
              "                                input.value = \"\";\n",
              "                            } else {\n",
              "                                const errMsg = (result && result.error) ? result.error : \"Unknown download error\";\n",
              "                                showToast(errMsg);\n",
              "                            }\n",
              "                        } catch (err) {\n",
              "                            showToast(\"Error: \" + err.message);\n",
              "                        } finally {\n",
              "                            btn.style.pointerEvents = 'auto';\n",
              "                            btn.style.opacity = '1';\n",
              "                            if (icon) { icon.classList.remove('fa-spin'); icon.innerText = 'download'; }\n",
              "                        }\n",
              "                    }\n",
              "\n",
              "                    function updateFourXAvailability() {\n",
              "                        const toggle = document.getElementById('fourXToggle');\n",
              "                        const switchWidget = toggle ? toggle.closest('.switch-widget') : null;\n",
              "                        // Robust element selector (style text par depend nahi karega)\n",
              "                        const subtext = toggle ? toggle.closest('.switch-row')?.querySelector('.component-label-group div span') : null;\n",
              "\n",
              "                        const activeCard = document.getElementById('customModelActiveCard');\n",
              "                        const activeTypeEl = document.getElementById('activeModelCardType');\n",
              "                        const isCustomEngine = (activeCard && activeCard.style.display !== 'none' && activeTypeEl && activeTypeEl.innerText.trim().toUpperCase() === 'ENGINE');\n",
              "                        const isCustomNormal = (typeof STATE_MODEL !== 'undefined' && STATE_MODEL === 'Custom' && STATE_ONNX_MODE === 'normal' && !isCustomEngine);\n",
              "\n",
              "                        if (toggle && switchWidget) {\n",
              "                            if (isCustomNormal) {\n",
              "                                toggle.checked = false;\n",
              "                                toggle.disabled = true;\n",
              "                                switchWidget.style.opacity = '0.35';\n",
              "                                switchWidget.style.pointerEvents = 'none';\n",
              "                                if (subtext) {\n",
              "                                    if (!subtext.dataset.origText) subtext.dataset.origText = subtext.innerText;\n",
              "                                    subtext.innerText = \"4X upscaling is disabled for .onnx models\";\n",
              "                                    subtext.style.color = \"var(--text-muted)\";\n",
              "                                }\n",
              "                            } else {\n",
              "                                toggle.disabled = false;\n",
              "                                switchWidget.style.opacity = '1';\n",
              "                                switchWidget.style.pointerEvents = 'auto';\n",
              "                                if (subtext) {\n",
              "                                    subtext.innerText = subtext.dataset.origText || \"2-Pass AI mode (Takes longer to render).\";\n",
              "                                    subtext.style.color = \"var(--highlight-cta)\";\n",
              "                                }\n",
              "                            }\n",
              "                        }\n",
              "                    }\n",
              "\n",
              "                    function selectOnnxMode(mode, showModal = false) {\n",
              "                        STATE_ONNX_MODE = mode;\n",
              "                        const btnNorm = document.getElementById('btnOnnxNormal');\n",
              "                        const btnConv = document.getElementById('btnOnnxConvert');\n",
              "                        if (btnNorm && btnConv) {\n",
              "                            btnNorm.classList.toggle('active', mode === 'normal');\n",
              "                            btnConv.classList.toggle('active', mode === 'convert');\n",
              "                        }\n",
              "                        updateFourXAvailability();\n",
              "                        if (showModal) {\n",
              "                            openOnnxInfoModal();\n",
              "                        }\n",
              "                    }\n",
              "\n",
              "                    function openOnnxInfoModal() {\n",
              "                        const m = document.getElementById('onnxInfoModal');\n",
              "                        if (m) m.classList.add('show');\n",
              "                    }\n",
              "\n",
              "                    if (typeof google !== 'undefined' && google.colab && google.colab.kernel && !google.colab.kernel._hasHookedOnnxPayload) {\n",
              "                        const prevInvoke = google.colab.kernel.invokeFunction;\n",
              "                        google.colab.kernel.invokeFunction = function(name, args, kwargs) {\n",
              "                            if (name === 'notebook.command' && args && args[0]) {\n",
              "                                try {\n",
              "                                    let data = JSON.parse(args[0]);\n",
              "                                    if (data.command === 'START') {\n",
              "                                        const activeCard = document.getElementById('customModelActiveCard');\n",
              "                                        const activeTypeEl = document.getElementById('activeModelCardType');\n",
              "                                        const isCustomEngine = (activeCard && activeCard.style.display !== 'none' && activeTypeEl && activeTypeEl.innerText.trim().toUpperCase() === 'ENGINE');\n",
              "                                        data.onnxMode = STATE_ONNX_MODE;\n",
              "                                        if (data.model === 'Custom' && STATE_ONNX_MODE === 'normal' && !isCustomEngine) {\n",
              "                                            data.fourXUpscale = false;\n",
              "                                        }\n",
              "                                        args[0] = JSON.stringify(data);\n",
              "                                    }\n",
              "                                } catch(e) {}\n",
              "                            }\n",
              "                            return prevInvoke.apply(this, arguments);\n",
              "                        };\n",
              "                        google.colab.kernel._hasHookedOnnxPayload = true;\n",
              "                    }\n",
              "\n",
              "                    // Restore saved custom model card on page reload\n",
              "                    try {\n",
              "                        const savedMeta = localStorage.getItem('cs_custom_model_meta');\n",
              "                        if (savedMeta) {\n",
              "                            renderCustomModelCard(JSON.parse(savedMeta));\n",
              "                        }\n",
              "                    } catch(e) {}\n",
              "\n",
              "                    setTimeout(updateFourXAvailability, 150);\n",
              "                </script>\n",
              "            </div>\n",
              "\n",
              "            <!-- EXTRA TUNING SECTION (Clean Collapsible Accordion with Arrow) -->\n",
              "            <div class=\"compose-card span-full\" style=\"border: 1px solid var(--primary-yellow); background: linear-gradient(180deg, var(--surface-card) 0%, var(--surface-inner) 100%); padding: 8.5px 12px !important; gap: 0px !important; border-radius: 18px; min-height: auto !important;\">\n",
              "                <div class=\"component-label-group interactable-node\" style=\"cursor: pointer; display: flex; justify-content: space-between; align-items: center; width: 100%; min-height: 22px; user-select: none;\" onclick=\"toggleTuning()\">\n",
              "                    <div style=\"display:flex; align-items:center; gap:8px;\">\n",
              "                        <span class=\"material-icons-round icon\" style=\"color:var(--primary-yellow); font-size: 17px;\">tune</span>\n",
              "                        <h3 class=\"component-title\" style=\"margin:0; font-size: 12.5px; font-weight: 800; line-height: 1.2;\">Extra Tuning & LUT</h3>\n",
              "                    </div>\n",
              "                    <span class=\"material-icons-round\" id=\"tuningArrow\" style=\"color:var(--primary-yellow); font-size: 20px; line-height: 1; transition: transform 0.25s ease;\">expand_more</span>\n",
              "                </div>\n",
              "\n",
              "                <!-- Clean Single-Div Smooth Accordion (Zero Broken Tags) -->\n",
              "                <div id=\"tuningContent\" style=\"max-height: 0px; overflow: hidden; opacity: 0; display: flex; flex-direction: column; gap: 12px; margin-top: 0px; border-top: 1px dashed transparent; padding-top: 0px; transition: max-height 0.3s cubic-bezier(0.2, 0.8, 0.2, 1), opacity 0.22s ease, margin-top 0.25s ease, padding-top 0.25s ease;\">\n",
              "                    <div class=\"dashboard-layout\" style=\"margin-top: 2px;\">\n",
              "                        <div style=\"display:flex; flex-direction:column; gap:6px;\">\n",
              "                            <div class=\"slider-info-row\">\n",
              "                                <span style=\"font-size:13px; font-weight:700; color:var(--text-primary);\"><span class=\"material-icons-round icon\" style=\"font-size:15px; vertical-align:middle; color:var(--primary-yellow);\">grain</span> Recover Original Details</span>\n",
              "                                <span class=\"badge-pills\" id=\"recoverDetailsNum\">0%</span>\n",
              "                            </div>\n",
              "                            <div class=\"range-container\">\n",
              "                                <input type=\"range\" class=\"range-input interactable-node\" id=\"recoverDetailsSlider\" min=\"0\" max=\"100\" value=\"0\" oninput=\"document.getElementById('recoverDetailsNum').innerText = this.value + '%'\">\n",
              "                            </div>\n",
              "                            <div class=\"slider-labels\"><span>Disabled</span><span>100% (High Texture)</span></div>\n",
              "                        </div>\n",
              "\n",
              "                        <div style=\"display:flex; flex-direction:column; gap:6px;\">\n",
              "                            <div class=\"slider-info-row\">\n",
              "                                <span style=\"font-size:13px; font-weight:700; color:var(--text-primary);\"><span class=\"material-icons-round icon\" style=\"font-size:15px; vertical-align:middle; color:var(--primary-yellow);\">details</span> Sharpen / De-Blur</span>\n",
              "                                <span class=\"badge-pills\" id=\"sharpenNum\">0%</span>\n",
              "                            </div>\n",
              "                            <div class=\"range-container\">\n",
              "                                <input type=\"range\" class=\"range-input interactable-node\" id=\"sharpenSlider\" min=\"0\" max=\"100\" value=\"0\" oninput=\"document.getElementById('sharpenNum').innerText = this.value + '%'\">\n",
              "                            </div>\n",
              "                            <div class=\"slider-labels\"><span>Soft</span><span>Crisp Edges</span></div>\n",
              "                        </div>\n",
              "\n",
              "                        <div style=\"display:flex; flex-direction:column; gap:6px;\">\n",
              "                            <div class=\"slider-info-row\">\n",
              "                                <span style=\"font-size:13px; font-weight:700; color:var(--text-primary);\"><span class=\"material-icons-round icon\" style=\"font-size:15px; vertical-align:middle; color:var(--primary-yellow);\">filter_vintage</span> Reduce Noise / Denoise</span>\n",
              "                                <span class=\"badge-pills\" id=\"denoiseNum\">0%</span>\n",
              "                            </div>\n",
              "                            <div class=\"range-container\">\n",
              "                                <input type=\"range\" class=\"range-input interactable-node\" id=\"denoiseSlider\" min=\"0\" max=\"100\" value=\"0\" oninput=\"document.getElementById('denoiseNum').innerText = this.value + '%'\">\n",
              "                            </div>\n",
              "                            <div class=\"slider-labels\"><span>Raw</span><span>Clean Smoothing</span></div>\n",
              "                        </div>\n",
              "\n",
              "                        <div style=\"display:flex; flex-direction:column; gap:6px;\">\n",
              "                            <div class=\"slider-info-row\">\n",
              "                                <span style=\"font-size:13px; font-weight:700; color:var(--text-primary);\"><span class=\"material-icons-round icon\" style=\"font-size:15px; vertical-align:middle; color:var(--primary-yellow);\">blur_off</span> De-Halo / Anti-Ringing</span>\n",
              "                                <span class=\"badge-pills\" id=\"dehaloNum\">0%</span>\n",
              "                            </div>\n",
              "                            <div class=\"range-container\">\n",
              "                                <input type=\"range\" class=\"range-input interactable-node\" id=\"dehaloSlider\" min=\"0\" max=\"100\" value=\"0\" oninput=\"document.getElementById('dehaloNum').innerText = this.value + '%'\">\n",
              "                            </div>\n",
              "                            <div class=\"slider-labels\"><span>Off</span><span>Max Edge Clean</span></div>\n",
              "                        </div>\n",
              "\n",
              "                        <!-- Film Grain Slider (Cinematic Texture & Anti-Banding) -->\n",
              "                        <div style=\"display:flex; flex-direction:column; gap:6px;\">\n",
              "                            <div class=\"slider-info-row\">\n",
              "                                <span style=\"font-size:13px; font-weight:700; color:var(--text-primary);\"><span class=\"material-icons-round icon\" style=\"font-size:15px; vertical-align:middle; color:var(--primary-yellow);\">grain</span> Film Grain (Anti-Banding)</span>\n",
              "                                <span class=\"badge-pills\" id=\"grainNum\">0%</span>\n",
              "                            </div>\n",
              "                            <div class=\"range-container\">\n",
              "                                <input type=\"range\" class=\"range-input interactable-node\" id=\"grainSlider\" min=\"0\" max=\"100\" value=\"0\" oninput=\"document.getElementById('grainNum').innerText = this.value + '%'\">\n",
              "                            </div>\n",
              "                            <div class=\"slider-labels\"><span>Disabled</span><span>100% (High Grain)</span></div>\n",
              "                        </div>\n",
              "                    </div>\n",
              "\n",
              "                    <!-- Custom CC / 3D LUT (.cube / Hald) Section -->\n",
              "                    <div style=\"border-top: 1px dashed var(--border-distinct); margin-top: 4px; padding-top: 10px; display: flex; flex-direction: column; gap: 8px;\">\n",
              "                        <div class=\"switch-row\">\n",
              "                            <div class=\"component-label-group\">\n",
              "                                <span class=\"material-icons-round icon\" style=\"color:var(--primary-yellow);\">palette</span>\n",
              "                                <div style=\"display:flex; flex-direction:column;\">\n",
              "                                    <h3 class=\"component-title\" style=\"margin:0;\">Apply CC / LUT (.cube / Hald)</h3>\n",
              "                                    <span style=\"font-size:11px; color:var(--text-muted); font-weight:500;\">Export AE CC as .cube or Hald image.</span>\n",
              "                                </div>\n",
              "                            </div>\n",
              "                            <label class=\"switch-widget\"><input type=\"checkbox\" id=\"lutToggle\"><span class=\"switch-slider\"></span></label>\n",
              "                        </div>\n",
              "\n",
              "                        <!-- Upload Button & File Picker -->\n",
              "                        <!-- Multi-LUT List Container with Radio/Checkbox Selection -->\n",
              "                        <div id=\"lutListContainer\" style=\"display: flex; flex-direction: column; gap: 6px; max-height: 130px; overflow-y: auto; padding-right: 2px;\"></div>\n",
              "\n",
              "                        <!-- Add LUT / Hald Button -->\n",
              "                        <div style=\"display: flex; gap: 8px; align-items: center; width: 100%;\">\n",
              "                            <button class=\"model-upload-btn interactable-node\" style=\"flex: 1; border-radius: 100px; padding: 8px 16px; font-size: 12px;\" onclick=\"document.getElementById('nativeLutInput').click()\">\n",
              "                                <span class=\"material-icons-round icon\" style=\"font-size:16px; color:var(--primary-yellow);\">add</span>\n",
              "                                <span id=\"lutUploadLabel\">Add .cube / Hald Image</span>\n",
              "                            </button>\n",
              "                            <input type=\"file\" id=\"nativeLutInput\" accept=\".cube,.png,.jpg,.jpeg,.webp\" style=\"display:none;\" onchange=\"handleLutUpload(this)\">\n",
              "                        </div>\n",
              "\n",
              "                        <!-- Dedicated LUT Strength / Intensity Slider -->\n",
              "                        <div style=\"display: flex; flex-direction: column; gap: 2px; margin-top: 4px;\">\n",
              "                            <div class=\"slider-info-row\">\n",
              "                                <span style=\"font-size:12px; font-weight:700; color:var(--text-primary);\"><span class=\"material-icons-round icon\" style=\"font-size:14px; vertical-align:middle; color:var(--primary-yellow);\">opacity</span> LUT Strength / Intensity</span>\n",
              "                                <span class=\"badge-pills\" id=\"lutStrengthNum\" style=\"font-size:12px;\">100%</span>\n",
              "                            </div>\n",
              "                            <div class=\"range-container\" style=\"padding: 2px 0;\">\n",
              "                                <input type=\"range\" class=\"range-input interactable-node\" id=\"lutStrengthSlider\" min=\"0\" max=\"100\" value=\"100\" oninput=\"document.getElementById('lutStrengthNum').innerText = this.value + '%'\" style=\"height:4px;\">\n",
              "                            </div>\n",
              "                        </div>\n",
              "                    </div>\n",
              "                </div>\n",
              "            </div>\n",
              "\n",
              "            <script>\n",
              "                let ACTIVE_LUT_PATH = localStorage.getItem('cs_active_lut') || '';\n",
              "\n",
              "                let _tuningOpen = false;\n",
              "                (function initTwixtorTuning() {\n",
              "                    const c = document.getElementById('tuningContent');\n",
              "                    if (!c) return;\n",
              "                    const arrow = document.getElementById('tuningArrow');\n",
              "                    if (arrow) arrow.style.transition = 'transform 0.28s cubic-bezier(0.2, 0.8, 0.2, 1)';\n",
              "\n",
              "                    let inner = document.getElementById('tuningInner');\n",
              "                    if (!inner) {\n",
              "                        const middle = document.createElement('div');\n",
              "                        middle.style.cssText = 'overflow: hidden; min-height: 0; width: 100%;';\n",
              "                        inner = document.createElement('div');\n",
              "                        inner.id = 'tuningInner';\n",
              "                        inner.style.cssText = 'display: flex; flex-direction: column; gap: 12px; margin-top: 10px; border-top: 1px dashed var(--border-distinct); padding-top: 12px; opacity: 0; pointer-events: none; transform: translateY(-4px); transition: opacity 0.22s ease, transform 0.24s cubic-bezier(0.2, 0.8, 0.2, 1);';\n",
              "                        while (c.firstChild) inner.appendChild(c.firstChild);\n",
              "                        middle.appendChild(inner);\n",
              "                        c.appendChild(middle);\n",
              "                    }\n",
              "                    c.style.cssText = 'display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.28s cubic-bezier(0.2, 0.8, 0.2, 1); width: 100%;';\n",
              "                })();\n",
              "\n",
              "                function toggleTuning(forceOpen) {\n",
              "                    const wrapper = document.getElementById('tuningContent');\n",
              "                    const inner = document.getElementById('tuningInner');\n",
              "                    const arrow = document.getElementById('tuningArrow');\n",
              "                    if (!wrapper || !inner) return;\n",
              "\n",
              "                    _tuningOpen = (typeof forceOpen === 'boolean') ? forceOpen : !_tuningOpen;\n",
              "                    if (_tuningOpen) {\n",
              "                        wrapper.style.gridTemplateRows = '1fr';\n",
              "                        inner.style.opacity = '1';\n",
              "                        inner.style.transform = 'translateY(0)';\n",
              "                        inner.style.pointerEvents = 'auto';\n",
              "                        if (arrow) arrow.style.transform = 'rotate(180deg)';\n",
              "                    } else {\n",
              "                        wrapper.style.gridTemplateRows = '0fr';\n",
              "                        inner.style.opacity = '0';\n",
              "                        inner.style.transform = 'translateY(-4px)';\n",
              "                        inner.style.pointerEvents = 'none';\n",
              "                        if (arrow) arrow.style.transform = 'rotate(0deg)';\n",
              "                    }\n",
              "                }\n",
              "\n",
              "                function renderLutList(luts) {\n",
              "                    const container = document.getElementById('lutListContainer');\n",
              "                    if (!container) return;\n",
              "\n",
              "                    if (!luts || luts.length === 0) {\n",
              "                        container.innerHTML = '<div style=\"font-size: 11px; color: var(--text-muted); text-align: center; padding: 4px 0;\">No LUTs in vault. Click below to add.</div>';\n",
              "                        ACTIVE_LUT_PATH = '';\n",
              "                        return;\n",
              "                    }\n",
              "\n",
              "                    // If active LUT path is empty or not in list, default to first LUT\n",
              "                    const paths = luts.map(l => l.path);\n",
              "                    if (!ACTIVE_LUT_PATH || !paths.includes(ACTIVE_LUT_PATH)) {\n",
              "                        ACTIVE_LUT_PATH = luts[0].path;\n",
              "                        localStorage.setItem('cs_active_lut', ACTIVE_LUT_PATH);\n",
              "                    }\n",
              "\n",
              "                    let html = '';\n",
              "                    luts.forEach((item) => {\n",
              "                        const isChecked = (item.path === ACTIVE_LUT_PATH) ? 'checked' : '';\n",
              "                        const b64P = btoa(unescape(encodeURIComponent(item.path)));\n",
              "                        html += `\n",
              "                        <div style=\"display:flex; align-items:center; justify-content:space-between; background:var(--surface-inner); border:1px solid var(--border-distinct); border-radius:10px; padding:6px 10px; gap:8px;\">\n",
              "                            <label style=\"display:flex; align-items:center; gap:8px; flex:1; min-width:0; cursor:pointer; margin:0;\">\n",
              "                                <input type=\"radio\" name=\"lut_select_radio\" value=\"${b64P}\" ${isChecked} onchange=\"selectActiveLut('${b64P}')\" style=\"width:16px; height:16px; accent-color:var(--primary-yellow); cursor:pointer;\">\n",
              "                                <span style=\"font-size:11px; font-weight:700; color:var(--text-primary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;\">${escapeHTML(item.name)}</span>\n",
              "                            </label>\n",
              "                            <span class=\"material-icons-round\" style=\"font-size:16px; color:var(--text-muted); cursor:pointer; transition:0.2s;\" onclick=\"deleteLutItem('${b64P}')\" title=\"Remove LUT\">close</span>\n",
              "                        </div>`;\n",
              "                    });\n",
              "                    container.innerHTML = html;\n",
              "                }\n",
              "\n",
              "                function selectActiveLut(b64Path) {\n",
              "                    ACTIVE_LUT_PATH = decodeURIComponent(escape(atob(b64Path)));\n",
              "                    localStorage.setItem('cs_active_lut', ACTIVE_LUT_PATH);\n",
              "                    const lutToggle = document.getElementById('lutToggle');\n",
              "                    if (lutToggle) lutToggle.checked = true;\n",
              "                }\n",
              "\n",
              "                function deleteLutItem(b64Path) {\n",
              "                    const targetPath = decodeURIComponent(escape(atob(b64Path)));\n",
              "                    google.colab.kernel.invokeFunction('notebook.command', [JSON.stringify({\n",
              "                        command: \"DELETE_LUT\",\n",
              "                        path: targetPath\n",
              "                    })], {}).then(() => {\n",
              "                        triggerPythonRefresh();\n",
              "                        showToast(\"LUT removed from vault\");\n",
              "                    });\n",
              "                }\n",
              "\n",
              "                function handleLutUpload(input) {\n",
              "                    if (!input.files || input.files.length === 0) return;\n",
              "                    const file = input.files[0];\n",
              "                    const fname = file.name.toLowerCase();\n",
              "                    const validExts = ['.cube', '.png', '.jpg', '.jpeg', '.webp'];\n",
              "                    const isValid = validExts.some(ext => fname.endsWith(ext));\n",
              "\n",
              "                    if (!isValid) {\n",
              "                        showToast(\"Please select a valid .cube LUT or Hald image (.png, .jpg).\");\n",
              "                        return;\n",
              "                    }\n",
              "\n",
              "                    const label = document.getElementById('lutUploadLabel');\n",
              "                    if (label) label.innerText = `Uploading...`;\n",
              "\n",
              "                    const reader = new FileReader();\n",
              "                    reader.onload = function(e) {\n",
              "                        const b64 = e.target.result.split(',')[1];\n",
              "                        google.colab.kernel.invokeFunction('notebook.command', [JSON.stringify({\n",
              "                            command: \"UPLOAD_LUT\",\n",
              "                            filename: file.name,\n",
              "                            data: b64\n",
              "                        })], {}).then(res => {\n",
              "                            const r = res.data['application/json'];\n",
              "                            if (r && r.success) {\n",
              "                                if (label) label.innerText = `+ Add .cube / Hald Image`;\n",
              "                                ACTIVE_LUT_PATH = r.path;\n",
              "                                localStorage.setItem('cs_active_lut', ACTIVE_LUT_PATH);\n",
              "                                const lutToggle = document.getElementById('lutToggle');\n",
              "                                if (lutToggle) lutToggle.checked = true;\n",
              "                                const content = document.getElementById('tuningContent');\n",
              "                                if (content) content.style.display = 'flex';\n",
              "                                const arrow = document.getElementById('tuningArrow');\n",
              "                                if (arrow) arrow.style.transform = 'rotate(180deg)';\n",
              "                                triggerPythonRefresh();\n",
              "                                showToast(`LUT \"${escapeHTML(file.name)}\" added & selected!`);\n",
              "                            } else {\n",
              "                                if (label) label.innerText = \"+ Add .cube / Hald Image\";\n",
              "                                showToast(\"Failed to upload LUT: \" + (r?.error || \"unknown error\"));\n",
              "                            }\n",
              "                        }).catch(err => {\n",
              "                            if (label) label.innerText = \"+ Add .cube / Hald Image\";\n",
              "                            showToast(\"Error uploading LUT: \" + err.message);\n",
              "                        });\n",
              "                    };\n",
              "                    reader.readAsDataURL(file);\n",
              "                }\n",
              "            </script>\n",
              "\n",
              "            <!-- Dedicated 4X Upscaling Card (Directly Below Tuning Sliders & LUT) -->\n",
              "            <div class=\"compose-card span-full\">\n",
              "                <div class=\"switch-row\" style=\"padding: 0;\">\n",
              "                    <div class=\"component-label-group\">\n",
              "                        <span class=\"material-icons-round icon\" style=\"color:var(--primary-yellow); font-size: 18px;\">auto_awesome</span>\n",
              "                        <div style=\"display:flex; flex-direction:column;\">\n",
              "                            <h3 class=\"component-title\" style=\"margin:0; font-size: 13px; font-weight: 800; color: var(--text-primary);\">4X Upscaling (2-Pass AI)</h3>\n",
              "                            <span style=\"font-size: 11px; color: var(--highlight-cta); font-weight: 600; white-space: nowrap;\">2-Pass AI mode (Takes longer to render).</span>\n",
              "                        </div>\n",
              "                    </div>\n",
              "                    <label class=\"switch-widget\"><input type=\"checkbox\" id=\"fourXToggle\" onchange=\"handleFourXToggle(this)\"><span class=\"switch-slider\"></span></label>\n",
              "                </div>\n",
              "\n",
              "                <!-- 4X Speed Mode Selection (Fast Default vs Quality) -->\n",
              "                <div id=\"fourXSpeedOptions\" style=\"display:none; flex-direction:column; gap:6px; margin-top:6px; border-top:1px dashed var(--border-distinct); padding-top:8px;\">\n",
              "                    <div style=\"display:flex; justify-content:space-between; align-items:center;\">\n",
              "                        <span style=\"font-size:11px; font-weight:700; color:var(--text-primary);\">4X Mode:</span>\n",
              "                        <span style=\"font-size:10px; color:var(--text-muted); font-weight:600;\" id=\"fourXSpeedDesc\">Fast: Pre-scales to fit 8192px limit directly</span>\n",
              "                    </div>\n",
              "                    <div style=\"display:flex; gap:6px; width:100%;\">\n",
              "                        <button class=\"block-selector interactable-node active\" id=\"btn4XFast\" onclick=\"selectFourXSpeed('fast')\" style=\"flex:1; padding:8px 6px; font-size:11px;\">Fast (Pre-Scale)</button>\n",
              "                        <button class=\"block-selector interactable-node\" id=\"btn4XQuality\" onclick=\"selectFourXSpeed('quality')\" style=\"flex:1; padding:8px 6px; font-size:11px;\">Quality (Post-Scale)</button>\n",
              "                    </div>\n",
              "                </div>\n",
              "            </div>\n",
              "\n",
              "            <div class=\"compose-card span-full\">\n",
              "                <div class=\"switch-row\" style=\"padding: 0;\">\n",
              "                    <div class=\"component-label-group\">\n",
              "                        <span class=\"material-icons-round icon\" style=\"color:var(--primary-yellow); font-size: 18px;\">movie_filter</span>\n",
              "                        <div style=\"display:flex; flex-direction:column;\">\n",
              "                            <h3 class=\"component-title\" style=\"margin:0; font-size: 13px; font-weight: 800; color: var(--text-primary);\">BOOST FPS</h3>\n",
              "                            <span style=\"font-size: 11px; color: var(--text-muted); font-weight: 600;\">Videos only · runs after upscale · RIFE 4.26</span>\n",
              "                        </div>\n",
              "                    </div>\n",
              "                    <label class=\"switch-widget\"><input type=\"checkbox\" id=\"frameInterpToggle\" onchange=\"handleFrameInterpToggle(this)\"><span class=\"switch-slider\"></span></label>\n",
              "                </div>\n",
              "                <div id=\"frameInterpOptions\" style=\"display:none; flex-direction:column; gap:6px; margin-top:6px; border-top:1px dashed var(--border-distinct); padding-top:8px;\">\n",
              "                    <div style=\"display:flex; justify-content:space-between; align-items:center;\">\n",
              "                        <span style=\"font-size:11px; font-weight:700; color:var(--text-primary);\">Target FPS:</span>\n",
              "                        <span style=\"font-size:10px; color:var(--text-muted); font-weight:600;\" id=\"frameInterpDesc\">Output will be 60 FPS</span>\n",
              "                    </div>\n",
              "                    <div style=\"display:flex; gap:6px; width:100%;\">\n",
              "                        <button type=\"button\" class=\"block-selector interactable-node active\" id=\"btnFps60\" onclick=\"selectFrameInterpFps('60')\" style=\"flex:1; padding:8px 6px; font-size:11px;\">60 FPS</button>\n",
              "                        <button type=\"button\" class=\"block-selector interactable-node\" id=\"btnFps120\" onclick=\"selectFrameInterpFps('120')\" style=\"flex:1; padding:8px 6px; font-size:11px;\">120 FPS</button>\n",
              "                        <button type=\"button\" class=\"block-selector interactable-node\" id=\"btnFpsCustom\" onclick=\"selectFrameInterpFps('custom')\" style=\"flex:1; padding:8px 6px; font-size:11px;\">CUSTOM</button>\n",
              "                    </div>\n",
              "                </div>\n",
              "            </div>\n",
              "            <script>\n",
              "                let STATE_RIFE_FPS_MODE = \"60\";\n",
              "                let STATE_RIFE_CUSTOM_FPS = 24;\n",
              "                let PREV_FPS_MODE = \"60\";\n",
              "                function handleFrameInterpToggle(input) {\n",
              "                    const opts = document.getElementById('frameInterpOptions');\n",
              "                    if (opts) opts.style.display = input.checked ? 'flex' : 'none';\n",
              "                }\n",
              "                function applyFrameInterpFps(mode) {\n",
              "                    STATE_RIFE_FPS_MODE = mode;\n",
              "                    PREV_FPS_MODE = mode;\n",
              "                    [\"60\", \"120\", \"custom\"].forEach(name => {\n",
              "                        const btn = document.getElementById(name === \"custom\" ? \"btnFpsCustom\" : (\"btnFps\" + name));\n",
              "                        if (btn) btn.classList.toggle(\"active\", name === mode);\n",
              "                    });\n",
              "                    const customBtn = document.getElementById(\"btnFpsCustom\");\n",
              "                    if (customBtn) customBtn.innerText = mode === \"custom\" ? (String(STATE_RIFE_CUSTOM_FPS) + \" FPS\") : \"CUSTOM\";\n",
              "                    const desc = document.getElementById(\"frameInterpDesc\");\n",
              "                    if (desc) {\n",
              "                        const fps = mode === \"120\" ? 120 : mode === \"custom\" ? STATE_RIFE_CUSTOM_FPS : 60;\n",
              "                        desc.innerText = \"Output will be \" + fps + \" FPS\";\n",
              "                    }\n",
              "                }\n",
              "                function selectFrameInterpFps(mode) {\n",
              "                    if (mode === \"custom\") {\n",
              "                        const modal = document.getElementById(\"fpsModal\");\n",
              "                        const input = document.getElementById(\"customFpsInput\");\n",
              "                        const errorDiv = document.getElementById(\"customFpsError\");\n",
              "                        if (input) input.value = STATE_RIFE_CUSTOM_FPS;\n",
              "                        if (errorDiv) errorDiv.style.display = \"none\";\n",
              "                        if (modal) modal.classList.add(\"show\");\n",
              "                        if (input) input.focus();\n",
              "                        return;\n",
              "                    }\n",
              "                    applyFrameInterpFps(mode);\n",
              "                }\n",
              "                function closeCustomFpsModal() {\n",
              "                    const modal = document.getElementById(\"fpsModal\");\n",
              "                    const errorDiv = document.getElementById(\"customFpsError\");\n",
              "                    if (modal) modal.classList.remove(\"show\");\n",
              "                    if (errorDiv) errorDiv.style.display = \"none\";\n",
              "                    applyFrameInterpFps(PREV_FPS_MODE);\n",
              "                }\n",
              "                function saveCustomFps() {\n",
              "                    const raw = parseFloat(document.getElementById(\"customFpsInput\")?.value);\n",
              "                    const errorDiv = document.getElementById(\"customFpsError\");\n",
              "                    if (!isFinite(raw) || raw < 1 || raw > 240) {\n",
              "                        if (errorDiv) {\n",
              "                            errorDiv.innerText = \"FPS must be between 1 and 240.\";\n",
              "                            errorDiv.style.display = \"block\";\n",
              "                        }\n",
              "                        return;\n",
              "                    }\n",
              "                    STATE_RIFE_CUSTOM_FPS = Math.round(raw * 100) / 100;\n",
              "                    if (errorDiv) errorDiv.style.display = \"none\";\n",
              "                    applyFrameInterpFps(\"custom\");\n",
              "                    const modal = document.getElementById(\"fpsModal\");\n",
              "                    if (modal) modal.classList.remove(\"show\");\n",
              "                }\n",
              "                function readFrameInterpFps() {\n",
              "                    if (STATE_RIFE_FPS_MODE === \"120\") return 120;\n",
              "                    if (STATE_RIFE_FPS_MODE === \"custom\") {\n",
              "                        if (!isFinite(STATE_RIFE_CUSTOM_FPS) || STATE_RIFE_CUSTOM_FPS < 1 || STATE_RIFE_CUSTOM_FPS > 240) return null;\n",
              "                        return STATE_RIFE_CUSTOM_FPS;\n",
              "                    }\n",
              "                    return 60;\n",
              "                }\n",
              "            </script>\n",
              "\n",
              "            <!-- 4X UPSCALING INFO MODAL (Compact 250px Layout) -->\n",
              "            <div class=\"modal-backdrop\" id=\"fourXInfoModal\" style=\"display:none;\">\n",
              "                <div class=\"modal-card\" style=\"padding: 12px 14px; gap: 8px; max-width: 250px;\">\n",
              "                    <div style=\"display:flex; align-items:center; gap:6px; justify-content:center;\">\n",
              "                        <span class=\"material-icons-round\" style=\"color:var(--primary-yellow); font-size:18px;\">auto_awesome</span>\n",
              "                        <h4 class=\"modal-title\" style=\"font-size:12.5px; margin:0;\">4X Upscaling (2-Pass AI)</h4>\n",
              "                    </div>\n",
              "\n",
              "                    <div style=\"display:flex; flex-direction:column; gap:5px; font-size:9.5px; color:var(--text-secondary); line-height:1.4; background:var(--surface-inner); border:1px solid var(--border-distinct); border-radius:10px; padding:7px 9px; box-sizing: border-box; text-align: left;\">\n",
              "                        <div>\n",
              "                            <strong style=\"color:var(--primary-yellow); display:flex; align-items:center; gap:3px; margin-bottom:1px; font-size:10.5px;\">\n",
              "                                <span class=\"material-icons-round\" style=\"font-size:13px;\">speed</span> 2-Pass AI Mode:\n",
              "                            </strong>\n",
              "                            Media is processed in two consecutive AI passes for fine textures. Takes longer than standard mode.\n",
              "                        </div>\n",
              "\n",
              "                        <div style=\"border-top:1px dashed var(--border-distinct); padding-top:4px;\">\n",
              "                            <strong style=\"color:var(--primary-yellow); display:flex; align-items:center; gap:3px; margin-bottom:1px; font-size:10.5px;\">\n",
              "                                <span class=\"material-icons-round\" style=\"font-size:13px;\">aspect_ratio</span> 8192px Boundary Limit:\n",
              "                            </strong>\n",
              "                            Max video encoder limit is 8192px. Excess resolution fits automatically with 100% aspect ratio preserved.\n",
              "                        </div>\n",
              "                    </div>\n",
              "\n",
              "                    <div class=\"modal-actions\" style=\"margin-top:1px; gap:6px;\">\n",
              "                        <button class=\"modal-btn cancel interactable-node\" style=\"padding: 6px 10px; font-size: 10.5px;\" onclick=\"cancelFourXModal()\">Cancel</button>\n",
              "                        <button class=\"modal-btn save interactable-node\" style=\"padding: 6px 10px; font-size: 10.5px;\" onclick=\"confirmFourXModal()\">Continue</button>\n",
              "                    </div>\n",
              "                </div>\n",
              "            </div>\n",
              "\n",
              "            <script>\n",
              "                let STATE_FOUR_X_MODE = \"fast\";\n",
              "\n",
              "                function selectFourXSpeed(mode) {\n",
              "                    STATE_FOUR_X_MODE = mode;\n",
              "                    const bFast = document.getElementById('btn4XFast');\n",
              "                    const bQual = document.getElementById('btn4XQuality');\n",
              "                    const desc = document.getElementById('fourXSpeedDesc');\n",
              "                    if (bFast && bQual) {\n",
              "                        bFast.classList.toggle('active', mode === 'fast');\n",
              "                        bQual.classList.toggle('active', mode === 'quality');\n",
              "                    }\n",
              "                    if (desc) {\n",
              "                        desc.innerText = mode === 'fast'\n",
              "                            ? \"Fast: Pre-scales to fit 8192px limit directly\"\n",
              "                            : \"Quality: Full render + Post-downscale\";\n",
              "                    }\n",
              "                }\n",
              "\n",
              "                // Auto-disable Fast mode if selected media doesn't exceed 8192px at 4X (e.g. 1080p, 720p)\n",
              "                function updateFastModeAvailability() {\n",
              "                    const bFast = document.getElementById('btn4XFast');\n",
              "                    const desc = document.getElementById('fourXSpeedDesc');\n",
              "                    if (!bFast) return;\n",
              "\n",
              "                    let needsFast = false;\n",
              "                    const checkedBoxes = document.querySelectorAll('.file-cb:checked');\n",
              "\n",
              "                    checkedBoxes.forEach(cb => {\n",
              "                        const panel = cb.closest('.preview-panel');\n",
              "                        if (panel) {\n",
              "                            const metaText = panel.querySelector('.meta-sub-metrics')?.innerText || '';\n",
              "                            const match = metaText.match(/(\\d+)\\s*x\\s*(\\d+)/i);\n",
              "                            if (match) {\n",
              "                                const w = parseInt(match[1], 10);\n",
              "                                const h = parseInt(match[2], 10);\n",
              "                                // Agar 4X hone par 8192 se bada hoga, tabhi Fast mode ki zaroorat hai\n",
              "                                if ((w * 4) > 8192 || (h * 4) > 8192) {\n",
              "                                    needsFast = true;\n",
              "                                }\n",
              "                            }\n",
              "                        }\n",
              "                    });\n",
              "\n",
              "                    if (checkedBoxes.length > 0 && !needsFast) {\n",
              "                        bFast.disabled = true;\n",
              "                        bFast.style.opacity = '0.35';\n",
              "                        bFast.style.pointerEvents = 'none';\n",
              "                        selectFourXSpeed('quality');\n",
              "                        if (desc) desc.innerText = \"Fast mode disabled: Media does not exceed 8192px\";\n",
              "                    } else {\n",
              "                        bFast.disabled = false;\n",
              "                        bFast.style.opacity = '1';\n",
              "                        bFast.style.pointerEvents = 'auto';\n",
              "                        selectFourXSpeed('fast');\n",
              "                        if (desc) desc.innerText = \"Fast: Pre-scales to fit 8192px limit directly\";\n",
              "                    }\n",
              "                }\n",
              "\n",
              "                // Universal Dead-Center Fixer for Colab Iframes (Responsive Desktop/Mobile Scaling)\n",
              "                function renderModalDeadCenter(modalId) {\n",
              "                    const modal = document.getElementById(modalId);\n",
              "                    if (!modal) return null;\n",
              "\n",
              "                    if (modal.parentElement !== document.body) {\n",
              "                        document.body.appendChild(modal);\n",
              "                    }\n",
              "\n",
              "                    const isLargeScreen = window.innerWidth >= 768;\n",
              "\n",
              "                    modal.style.cssText = `\n",
              "                        position: fixed !important;\n",
              "                        top: 0 !important;\n",
              "                        left: 0 !important;\n",
              "                        right: 0 !important;\n",
              "                        bottom: 0 !important;\n",
              "                        width: 100% !important;\n",
              "                        height: 100% !important;\n",
              "                        margin: 0 !important;\n",
              "                        padding: ${isLargeScreen ? '20px' : '12px'} !important;\n",
              "                        box-sizing: border-box !important;\n",
              "                        display: flex !important;\n",
              "                        align-items: center !important;\n",
              "                        justify-content: center !important;\n",
              "                        z-index: 99999 !important;\n",
              "                        background-color: rgba(0, 0, 0, 0.78) !important;\n",
              "                        backdrop-filter: blur(6px) !important;\n",
              "                        opacity: 1 !important;\n",
              "                        pointer-events: auto !important;\n",
              "                        touch-action: none !important;\n",
              "                    `;\n",
              "\n",
              "                    const card = modal.querySelector('.modal-card');\n",
              "                    if (card) {\n",
              "                        card.style.cssText = `\n",
              "                            margin: auto !important;\n",
              "                            max-height: 85% !important;\n",
              "                            width: ${isLargeScreen ? '88%' : '84%'} !important;\n",
              "                            max-width: ${isLargeScreen ? '380px' : '250px'} !important;\n",
              "                            padding: ${isLargeScreen ? '22px 20px' : '12px 14px'} !important;\n",
              "                            border-radius: ${isLargeScreen ? '24px' : '18px'} !important;\n",
              "                            overflow-y: auto !important;\n",
              "                            box-sizing: border-box !important;\n",
              "                            position: relative !important;\n",
              "                            transform: none !important;\n",
              "                        `;\n",
              "                    }\n",
              "                    return modal;\n",
              "                }\n",
              "\n",
              "                function dismissModalCenter(modalId) {\n",
              "                    const modal = document.getElementById(modalId);\n",
              "                    if (modal) {\n",
              "                        modal.style.display = 'none';\n",
              "                        modal.style.opacity = '0';\n",
              "                        modal.style.pointerEvents = 'none';\n",
              "                        modal.classList.remove('show');\n",
              "                    }\n",
              "                }\n",
              "\n",
              "                // 4X Modal Controls\n",
              "                window.handleFourXToggle = function(input) {\n",
              "                    const speedOpts = document.getElementById('fourXSpeedOptions');\n",
              "                    if (input.checked) {\n",
              "                        renderModalDeadCenter('fourXInfoModal');\n",
              "                    } else {\n",
              "                        if (speedOpts) speedOpts.style.display = 'none';\n",
              "                    }\n",
              "                };\n",
              "\n",
              "                window.confirmFourXModal = function() {\n",
              "                    dismissModalCenter('fourXInfoModal');\n",
              "                    const toggle = document.getElementById('fourXToggle');\n",
              "                    if (toggle) toggle.checked = true;\n",
              "                    const speedOpts = document.getElementById('fourXSpeedOptions');\n",
              "                    if (speedOpts) speedOpts.style.display = 'flex';\n",
              "                };\n",
              "\n",
              "                window.cancelFourXModal = function() {\n",
              "                    dismissModalCenter('fourXInfoModal');\n",
              "                    const toggle = document.getElementById('fourXToggle');\n",
              "                    if (toggle) toggle.checked = false;\n",
              "                    const speedOpts = document.getElementById('fourXSpeedOptions');\n",
              "                    if (speedOpts) speedOpts.style.display = 'none';\n",
              "                };\n",
              "\n",
              "                // ONNX Info Modal Controls\n",
              "                window.openOnnxInfoModal = function() {\n",
              "                    renderModalDeadCenter('onnxInfoModal');\n",
              "                };\n",
              "\n",
              "                document.addEventListener('click', function(e) {\n",
              "                    if (e.target && (e.target.id === 'onnxInfoModal' || e.target.closest('#onnxInfoModal .modal-btn'))) {\n",
              "                        dismissModalCenter('onnxInfoModal');\n",
              "                    }\n",
              "                });\n",
              "\n",
              "                setTimeout(() => {\n",
              "                    dismissModalCenter('fourXInfoModal');\n",
              "                    dismissModalCenter('onnxInfoModal');\n",
              "                }, 100);\n",
              "            </script>\n",
              "\n",
              "            <div class=\"compose-card span-full\">\n",
              "                <div class=\"slider-info-row\">\n",
              "                    <div class=\"component-label-group\"><span class=\"material-icons-round icon\" style=\"font-size: 16px; color: var(--primary-yellow);\">tune</span><h3 class=\"component-title\" style=\"font-size: 12px;\">Video Quality CRF</h3></div>\n",
              "                    <div class=\"badge-pills\" id=\"crfLiveNum\">15</div>\n",
              "                </div>\n",
              "                <div class=\"range-container\">\n",
              "                    <input type=\"range\" class=\"range-input interactable-node\" id=\"optSlider\" min=\"1\" max=\"51\" value=\"15\" oninput=\"updateCrfDisplay(this.value)\">\n",
              "                </div>\n",
              "                <div class=\"slider-labels\"><span>Quality (1)</span><span>Speed (51)</span></div>\n",
              "            </div>\n",
              "\n",
              "            <div class=\"compose-card flex-col-grid\">\n",
              "                <div class=\"component-label-group\"><span class=\"material-icons-round icon\" style=\"font-size: 16px;\">aspect_ratio</span><h3 class=\"component-title\" style=\"font-size: 11.5px;\">Output Resolution</h3></div>\n",
              "                <div style=\"display:flex !important; flex-wrap:nowrap !important; gap:4px !important; width:100% !important;\">\n",
              "                    <button class=\"block-selector interactable-node active\" id=\"r0\" onclick=\"selectResolution('r0','UPSCALED')\" style=\"flex:1 1 0 !important; min-width:0 !important; height:23px !important; display:inline-flex !important; align-items:center !important; justify-content:center !important; padding:0 2px !important; font-size:10px !important;\">UPSCALED</button>\n",
              "                    <button class=\"block-selector interactable-node\" id=\"r1\" onclick=\"selectResolution('r1','1080P')\" style=\"flex:1 1 0 !important; min-width:0 !important; height:23px !important; display:inline-flex !important; align-items:center !important; justify-content:center !important; padding:0 2px !important; font-size:10px !important;\">1080P</button>\n",
              "                    <button class=\"block-selector interactable-node\" id=\"r2\" onclick=\"selectResolution('r2','Custom')\" style=\"flex:1 1 0 !important; min-width:0 !important; height:23px !important; display:inline-flex !important; align-items:center !important; justify-content:center !important; padding:0 2px !important; font-size:10px !important;\">Custom</button>\n",
              "                </div>\n",
              "            </div>\n",
              "\n",
              "            <div class=\"compose-card flex-col-grid\">\n",
              "                <div class=\"component-label-group\"><span class=\"material-icons-round icon\" style=\"font-size: 16px;\">biotech</span><h3 class=\"component-title\" style=\"font-size: 11.5px;\">Codec Target</h3></div>\n",
              "                <div style=\"display:flex !important; flex-wrap:nowrap !important; gap:6px !important; width:100% !important;\">\n",
              "                    <button class=\"block-selector interactable-node\" id=\"c1\" onclick=\"selectCodec('c1','H.264')\" style=\"flex:1 1 0 !important; min-width:0 !important; height:23px !important; display:inline-flex !important; align-items:center !important; justify-content:center !important; padding:0 4px !important; font-size:10px !important; border-radius:100px !important;\">H.264</button>\n",
              "                    <button class=\"block-selector interactable-node active\" id=\"c2\" onclick=\"selectCodec('c2','H.265')\" style=\"flex:1 1 0 !important; min-width:0 !important; height:23px !important; display:inline-flex !important; align-items:center !important; justify-content:center !important; padding:0 4px !important; font-size:10px !important; border-radius:100px !important;\">H.265</button>\n",
              "                </div>\n",
              "            </div>\n",
              "\n",
              "            <div class=\"compose-card span-full\">\n",
              "                <div class=\"switch-row\">\n",
              "                    <div class=\"component-label-group\"><span class=\"material-icons-round icon\">backup</span><h3 class=\"component-title\">Save exports to Drive</h3></div>\n",
              "                    <label class=\"switch-widget\"><input type=\"checkbox\" id=\"driveToggle\" onchange=\"handleDriveMount(this)\"><span class=\"switch-slider\"></span></label>\n",
              "                </div>\n",
              "                <div class=\"switch-row\">\n",
              "                    <div class=\"component-label-group\"><span class=\"material-icons-round icon\">download_for_offline</span><h3 class=\"component-title\">Automatic Downloads</h3></div>\n",
              "                    <label class=\"switch-widget\"><input type=\"checkbox\" id=\"downloadToggle\" checked><span class=\"switch-slider\"></span></label>\n",
              "                </div>\n",
              "\n",
              "                <div class=\"switch-row\">\n",
              "                    <div class=\"component-label-group\"><span class=\"material-icons-round icon\">audiotrack</span><h3 class=\"component-title\">Keep Audio</h3></div>\n",
              "                    <label class=\"switch-widget\"><input type=\"checkbox\" id=\"audioToggle\" checked><span class=\"switch-slider\"></span></label>\n",
              "                </div>\n",
              "\n",
              "                <!-- iPhone Compatibility Fix permanently active in background -->\n",
              "                <input type=\"checkbox\" id=\"iphoneFixToggle\" checked style=\"display: none;\">\n",
              "\n",
              "                <div class=\"switch-row\" style=\"margin-top: 8px; border-top: 1px dashed var(--border-distinct); padding-top: 10px; padding-bottom: 2px; position: relative;\">\n",
              "                    <div class=\"component-label-group\">\n",
              "                        <span class=\"material-icons-round icon\" style=\"font-size: 15px; color: var(--primary-yellow);\">speed</span>\n",
              "                        <h3 class=\"component-title\" style=\"font-size: 11px;\">Preset</h3>\n",
              "                    </div>\n",
              "                    <input type=\"hidden\" id=\"presetDropdown\" value=\"p4\">\n",
              "                    <div style=\"position: relative; display: inline-block;\">\n",
              "                        <button type=\"button\" id=\"presetDropdownBtn\" onclick=\"togglePresetMenu(event)\" style=\"display: inline-flex; align-items: center; justify-content: space-between; gap: 6px; background: var(--surface-inner); border: 1px solid var(--border-distinct); border-radius: 100px; padding: 2px 10px; color: var(--text-primary); font-family: var(--font); font-size: 10px; font-weight: 700; cursor: pointer; height: 23px; min-width: 105px; box-sizing: border-box; transition: all 0.2s ease;\">\n",
              "                            <span id=\"presetCurrentLabel\" style=\"white-space: nowrap;\">P4 (Medium)</span>\n",
              "                            <span class=\"material-icons-round\" id=\"presetChevron\" style=\"font-size: 14px; color: var(--primary-yellow); transition: transform 0.2s ease;\">expand_more</span>\n",
              "                        </button>\n",
              "                        <div id=\"presetMenuPopover\" style=\"display: none; position: absolute; bottom: calc(100% + 5px); right: 0; background: var(--surface-card); border: 1px solid var(--border-distinct); border-radius: 14px; box-shadow: var(--card-shadow); z-index: 250; min-width: 140px; padding: 4px; box-sizing: border-box; flex-direction: column; gap: 2px; backdrop-filter: blur(10px);\">\n",
              "                            <div class=\"preset-opt interactable-node\" onclick=\"selectPresetOption('p1', 'P1 (Fastest)')\" style=\"display: flex; align-items: center; justify-content: space-between; padding: 5px 8px; border-radius: 8px; font-size: 10px; font-weight: 700; color: var(--text-secondary); cursor: pointer; transition: 0.15s;\"><span>P1 (Fastest)</span></div>\n",
              "                            <div class=\"preset-opt interactable-node\" onclick=\"selectPresetOption('p2', 'P2')\" style=\"display: flex; align-items: center; justify-content: space-between; padding: 5px 8px; border-radius: 8px; font-size: 10px; font-weight: 700; color: var(--text-secondary); cursor: pointer; transition: 0.15s;\"><span>P2</span></div>\n",
              "                            <div class=\"preset-opt interactable-node\" onclick=\"selectPresetOption('p3', 'P3')\" style=\"display: flex; align-items: center; justify-content: space-between; padding: 5px 8px; border-radius: 8px; font-size: 10px; font-weight: 700; color: var(--text-secondary); cursor: pointer; transition: 0.15s;\"><span>P3</span></div>\n",
              "                            <div class=\"preset-opt interactable-node\" onclick=\"selectPresetOption('p4', 'P4 (Medium)')\" style=\"display: flex; align-items: center; justify-content: space-between; padding: 5px 8px; border-radius: 8px; font-size: 10px; font-weight: 800; color: var(--primary-yellow); background: var(--card-glow); cursor: pointer; transition: 0.15s;\"><span>P4 (Medium)</span><span class=\"material-icons-round\" style=\"font-size: 12px; color: var(--primary-yellow);\">check</span></div>\n",
              "                            <div class=\"preset-opt interactable-node\" onclick=\"selectPresetOption('p5', 'P5')\" style=\"display: flex; align-items: center; justify-content: space-between; padding: 5px 8px; border-radius: 8px; font-size: 10px; font-weight: 700; color: var(--text-secondary); cursor: pointer; transition: 0.15s;\"><span>P5</span></div>\n",
              "                            <div class=\"preset-opt interactable-node\" onclick=\"selectPresetOption('p6', 'P6')\" style=\"display: flex; align-items: center; justify-content: space-between; padding: 5px 8px; border-radius: 8px; font-size: 10px; font-weight: 700; color: var(--text-secondary); cursor: pointer; transition: 0.15s;\"><span>P6</span></div>\n",
              "                            <div class=\"preset-opt interactable-node\" onclick=\"selectPresetOption('p7', 'P7 (Slowest / Best)')\" style=\"display: flex; align-items: center; justify-content: space-between; padding: 5px 8px; border-radius: 8px; font-size: 10px; font-weight: 700; color: var(--text-secondary); cursor: pointer; transition: 0.15s;\"><span>P7 (Slowest / Best)</span></div>\n",
              "                        </div>\n",
              "                    </div>\n",
              "                    <script>\n",
              "                        function togglePresetMenu(e) {\n",
              "                            if (e) e.stopPropagation();\n",
              "                            const menu = document.getElementById('presetMenuPopover');\n",
              "                            const chev = document.getElementById('presetChevron');\n",
              "                            if (!menu) return;\n",
              "                            const isOpen = menu.style.display === 'flex';\n",
              "                            menu.style.display = isOpen ? 'none' : 'flex';\n",
              "                            if (chev) chev.style.transform = isOpen ? 'rotate(0deg)' : 'rotate(180deg)';\n",
              "                        }\n",
              "                        function selectPresetOption(val, label) {\n",
              "                            const inp = document.getElementById('presetDropdown');\n",
              "                            const lbl = document.getElementById('presetCurrentLabel');\n",
              "                            if (inp) inp.value = val;\n",
              "                            if (lbl) lbl.innerText = label;\n",
              "                            document.querySelectorAll('.preset-opt').forEach(opt => {\n",
              "                                const isTarget = opt.getAttribute('onclick')?.includes(`'${val}'`);\n",
              "                                opt.style.color = isTarget ? 'var(--primary-yellow)' : 'var(--text-secondary)';\n",
              "                                opt.style.background = isTarget ? 'var(--card-glow)' : 'transparent';\n",
              "                                opt.style.fontWeight = isTarget ? '800' : '700';\n",
              "                                const chk = opt.querySelector('.material-icons-round');\n",
              "                                if (isTarget && !chk) {\n",
              "                                    opt.insertAdjacentHTML('beforeend', '<span class=\"material-icons-round\" style=\"font-size: 12px; color: var(--primary-yellow);\">check</span>');\n",
              "                                } else if (!isTarget && chk) {\n",
              "                                    chk.remove();\n",
              "                                }\n",
              "                            });\n",
              "                            togglePresetMenu();\n",
              "                        }\n",
              "                        document.addEventListener('click', function(e) {\n",
              "                            const menu = document.getElementById('presetMenuPopover');\n",
              "                            const btn = document.getElementById('presetDropdownBtn');\n",
              "                            if (menu && menu.style.display === 'flex' && btn && !btn.contains(e.target)) {\n",
              "                                togglePresetMenu();\n",
              "                            }\n",
              "                        });\n",
              "                    </script>\n",
              "                </div>\n",
              "            </div>\n",
              "        </div>\n",
              "    </div>\n",
              "\n",
              "    <div id=\"view-rendering\" class=\"view-section\">\n",
              "        <div class=\"compose-card span-full modern-render-card\">\n",
