              "                    <i class=\"fa-brands fa-telegram\" style=\"color:#2AABEE;\"></i> Telegram\n",
              "                </a>\n",
              "                <a href=\"https://crown-project.pages.dev/\" target=\"_blank\" class=\"yt-render-tag interactable-node\">\n",
              "                    <i class=\"fa-solid fa-globe\" style=\"color:#10B981;\"></i> Website\n",
              "                </a>\n",
              "            </div>\n",
              "\n",
              "            <div class=\"wm-target\" style=\"position:relative; bottom:0; margin-top:20px; color:var(--text-muted); font-weight:600; z-index: 1;\"></div>\n",
              "        </div>\n",
              "\n",
              "        <div class=\"debug-terminal\" id=\"debugPanel\">\n",
              "            <h3><span class=\"material-icons-round\">bug_report</span> Pipeline Notice</h3>\n",
              "            <div class=\"debug-log-text\" id=\"debugLogText\"></div>\n",
              "        </div>\n",
              "    </div>\n",
              "\n",
              "    <div id=\"view-exports\" class=\"view-section\">\n",
              "        <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:4px; padding: 0 4px;\">\n",
              "            <h2 class=\"app-title-sub\" style=\"font-size: 13px; margin: 0; font-weight: 800;\">Exports</h2>\n",
              "            <div style=\"display:flex; gap:5px; align-items:center;\">\n",
              "                <!-- Compact 24px ZIP Download Button (CrownTwixtor Sizing) -->\n",
              "                <button class=\"interactable-node\" style=\"background: linear-gradient(135deg, var(--primary-yellow), var(--dark-yellow)); color: #000; border: none; padding: 3px 9px; border-radius: 100px; font-family: var(--font); font-size: 9.5px; font-weight: 800; cursor: pointer; display: flex; align-items: center; gap: 3px; box-shadow: 0 2px 6px var(--card-glow); height: 24px;\" onclick=\"createZipAndDownload()\">\n",
              "                    <span class=\"material-icons-round\" style=\"font-size: 12px;\">archive</span>\n",
              "                    <span>Download All (ZIP)</span>\n",
              "                </button>\n",
              "                <!-- Compact 24px Export Download Settings Button -->\n",
              "                <div class=\"circle-icon-btn interactable-node\" style=\"width: 24px; height: 24px;\" onclick=\"openExportSettingsModal()\" title=\"Download Settings\">\n",
              "                    <span class=\"material-icons-round icon\" style=\"font-size: 13px; color: var(--text-muted);\">settings</span>\n",
              "                </div>\n",
              "            </div>\n",
              "        </div>\n",
              "        <div class=\"dashboard-layout\" id=\"savedFilesContainer\">\n",
              "            <div class=\"empty-state\">\n",
              "                <span class=\"material-icons-round\" style=\"font-size:32px; margin-bottom:8px; display:block;\">inventory_2</span>No archives exported yet.\n",
              "                <div class=\"wm-target\" style=\"position:absolute; bottom:8px; right:8px; font-size:10px; color:var(--text-muted);\"></div>\n",
              "            </div>\n",
